function UI.sfx(name)
  local seq = SFX[name]
  if not seq or not UI.speaker then return end
  for i = 1, #seq do
    pcall(UI.speaker.playNote, seq[i][1], seq[i][3], seq[i][2])
  end
end

CU.ui = UI
