-- WRITE-OFF / lib/tiles.lua
-- The world is made of these. Every tile that can be landed on says how it hurts.

return function(CU)

local T = {}

-- solid    : blocks movement
-- platform : stand on the top, pass through from underneath, drop through with DOWN
-- climb    : up and down move one tile with no fall
-- liquid   : slows you, breaks falls by depth
-- hard     : blunt force multiplier on landing. 1.0 is bare stone.
-- sharp    : how much of the impact arrives as a puncture instead of a crush
-- cushion  : fraction of the fall absorbed before it reaches you
-- name     : what the player is told they landed on

local function tile(t) return t end

T.DEFS = {
  [" "] = tile{ id = "air", name = "open air", colour = "bg" },

  ["#"] = tile{ id = "stone", name = "bare stone", solid = true, colour = "stone",
                hard = 1.00, sharp = 0.05, cushion = 0.00,
                dig = 100, drop = "stone_chunk" },

  ["%"] = tile{ id = "packed", name = "packed gravel", solid = true, colour = "gravel",
                hard = 0.80, sharp = 0.10, cushion = 0.12,
                dig = 62, drop = "stone_chunk" },

  ["o"] = tile{ id = "rubble", name = "loose rubble", solid = true, colour = "gravel",
                hard = 0.72, sharp = 0.38, cushion = 0.16,
                dig = 38, drop = "stone_chunk" },

  ["^"] = tile{ id = "spikes", name = "broken rock", solid = true, colour = "spike",
                hard = 0.85, sharp = 0.90, cushion = 0.00,
                dig = 78, drop = "glass_shard" },

  ['"'] = tile{ id = "moss", name = "a moss bed", solid = true, colour = "moss",
                hard = 0.42, sharp = 0.00, cushion = 0.46,
                dig = 24, drop = "fibre" },

  ["~"] = tile{ id = "water", name = "water", liquid = true, colour = "water",
                hard = 0.55, sharp = 0.00, cushion = 0.35 },

  ["="] = tile{ id = "plank", name = "a plank deck", platform = true, colour = "wood",
                hard = 0.78, sharp = 0.14, cushion = 0.10,
                dig = 30, drop = "plastic_chunk" },

  ["|"] = tile{ id = "rope", name = "rope", climb = true, colour = "wood" },
  ["H"] = tile{ id = "ladder", name = "a ladder", climb = true, colour = "metal" },
  ["+"] = tile{ id = "scaffold", name = "scaffold", climb = true, platform = true,
                colour = "metal", hard = 0.80, sharp = 0.30, cushion = 0.08 },

  ["V"] = tile{ id = "shaft", name = "the shaft down", shaft = true, colour = "shaft" },
  ["A"] = tile{ id = "hatch", name = "the surface hatch", hatch = true, colour = "gold" },

  -- things you interact with. they sit on the floor and you stand on their tile.
  ["c"] = tile{ id = "crate", name = "a crate", prop = true, colour = "wood" },
  ["m"] = tile{ id = "medbox", name = "a med box", prop = true, colour = "medbox" },
  ["b"] = tile{ id = "body", name = "a body", prop = true, colour = "corpse" },
  ["t"] = tile{ id = "toolchest", name = "a tool chest", prop = true, colour = "metal" },
  ["d"] = tile{ id = "debris", name = "debris", prop = true, colour = "gravel" },
  ["g"] = tile{ id = "growth", name = "growth", prop = true, colour = "moss" },
  ["l"] = tile{ id = "locker", name = "a locker", prop = true, colour = "metal" },
  ["h"] = tile{ id = "cache", name = "a sealed cache", prop = true, colour = "gold" },

  -- traps. all of them sit at standing height, so you walk into them.
  ["I"] = tile{ id = "impaler", name = "a spike", trap = true, colour = "spike" },
  ["J"] = tile{ id = "jumppad", name = "a launch plate", trap = true, colour = "metal" },
  ["K"] = tile{ id = "beartrap", name = "a leg trap", trap = true, colour = "metal" },

  -- pods: a hull you cannot break, doors you walk through, and what is inside
  ["B"] = tile{ id = "hull", name = "pod hull", solid = true, colour = "metal",
                hard = 0.80, sharp = 0.20, cushion = 0.10 },
  ["D"] = tile{ id = "door", name = "the pod door", colour = "metal" },
  ["T"] = tile{ id = "trader", name = "a trader", fixture = true, colour = "gold" },
  ["Z"] = tile{ id = "thermostat", name = "the thermostat", fixture = true, colour = "metal" },
  ["Y"] = tile{ id = "shower", name = "the decontamination shower", fixture = true,
                colour = "water" },

  -- fixtures
  ["W"] = tile{ id = "bench", name = "a workbench", fixture = true, colour = "wood" },
  ["C"] = tile{ id = "charger", name = "a charge post", fixture = true, colour = "metal" },
  ["P"] = tile{ id = "pod", name = "a life pod", fixture = true, colour = "medbox" },
  ["S"] = tile{ id = "spring", name = "a spring", fixture = true, colour = "water" },
  ["F"] = tile{ id = "heater", name = "an ion heater", fixture = true, colour = "spike" },
  ["X"] = tile{ id = "cargo", name = "the cargo crate", fixture = true, colour = "gold" },
  ["n"] = tile{ id = "note", name = "paper", fixture = true, colour = "gold" },
}

function T.get(ch) return T.DEFS[ch] or T.DEFS[" "] end

function T.isSolid(ch)
  local d = T.DEFS[ch]
  return d and d.solid or false
end

-- Something you can stand on the top of.
function T.isFloor(ch)
  local d = T.DEFS[ch]
  if not d then return false end
  return d.solid or d.platform or d.prop or d.fixture or false
end

function T.isClimb(ch)
  local d = T.DEFS[ch]
  return d and d.climb or false
end

function T.isLiquid(ch)
  local d = T.DEFS[ch]
  return d and d.liquid or false
end

-- Can the player's body occupy this tile?
function T.passable(ch)
  local d = T.DEFS[ch]
  if not d then return true end
  if d.solid then return false end
  return true
end

-- Landing surface properties, with sane defaults for anything unusual.
-- Work needed to break through, or nil if it cannot be mined.
function T.isTrap(ch)
  local d = T.DEFS[ch]
  return d and d.trap or false
end

function T.digCost(ch)
  local d = T.DEFS[ch]
  if not d then return nil end
  return d.dig
end

function T.digDrop(ch)
  local d = T.DEFS[ch]
  return d and d.drop or nil
end

function T.impact(ch)
  local d = T.DEFS[ch] or {}
  return {
    name = d.name or "the floor",
    hard = d.hard or 0.9,
    sharp = d.sharp or 0.1,
    cushion = d.cushion or 0.0,
  }
end

T.METRES_PER_TILE = 2

CU.tiles = T
return T

end
]=])

put("lib/body.lua", [=[
-- WRITE-OFF / lib/body.lua
-- The simulation. Seven limbs, one cardiovascular system, one clock.

return function(CU)

local U = CU.util
local D = CU.data
local T = D.TUNE

local B = {}

--------------------------------------------------------------------- construction

local function newLimb()
  return {
    skin = 100, muscle = 100,
    bone = "ok",            -- ok | dislocated | fractured
    boneTimer = 0,          -- minutes remaining
    bleed = 0,              -- L/min, external
    pain = 0,
    infection = 0, revealed = false,
    shrapnel = 0, burn = 0,
    dressing = nil,         -- { id, stop, absorb, soak }
    tourniquet = nil,       -- { time }
    splint = nil,           -- { mult }
    disinfect = 0,          -- seconds remaining
    chill = 0, warm = 0,
    amputated = false,
  }
end

function B.new(opts)
  opts = opts or {}
  local b = {
    limbs = {},
    blood = T.BLOOD_FULL, visc = 0,
    spo2 = 98, maxO2 = 100, hr = T.HR_BASE, bp = T.BP_BASE, resp = T.RESP_BASE,
    consciousness = 100, brain = 100,
    adren = 0, opioid = 0, tolerance = 0, withdrawal = 0,
    internal = 0, hemothorax = 0, embolism = false,
    fib = 0, arrest = false, arrestTime = 0, respArrest = false,
    temp = T.TEMP_BASE, wet = 0, oil = false,
    hunger = 100, thirst = 100, energy = 100, mood = 62, sick = 0, immunity = 100,
    sepsis = 0, weight = 62,
    traits = { str = 0, int = 0, res = 0 },
    gear = {},
    dead = false, cause = nil,
    seen = {}, painPeak = 0, held = nil,
  }
  for _, id in ipairs(D.LIMB_ORDER) do b.limbs[id] = newLimb() end
  if opts.traits then
    for k, v in pairs(opts.traits) do b.traits[k] = v end
  end
  return b
end

function B.limb(b, id) return b.limbs[id] end

--------------------------------------------------------------------- geometry

local ARM_LIMBS = { "larm", "rarm" }
local LEG_LIMBS = { "lleg", "rleg" }
local CORE_LIMBS = { "head", "thorax", "abdomen" }

function B.livingLimbs(b, filter)
  local out = {}
  for _, id in ipairs(D.LIMB_ORDER) do
    local l = b.limbs[id]
    if not l.amputated then
      if not filter or filter(id, l) then out[#out + 1] = id end
    end
  end
  return out
end

-- resolves a hazard/attack target descriptor into a limb id
function B.pickTarget(b, target, rng)
  local pool
  if target == "arm" then pool = { "larm", "rarm" }
  elseif target == "leg" then pool = { "lleg", "rleg" }
  elseif target == "head" then pool = { "head" }
  elseif target == "low" then pool = { "lleg", "rleg", "lleg", "rleg", "abdomen" }
  elseif target == "high" then pool = { "head", "thorax", "thorax", "larm", "rarm" }
  elseif target == "core" then pool = { "thorax", "abdomen" }
  else pool = { "head", "thorax", "thorax", "abdomen", "abdomen", "larm", "rarm", "lleg", "rleg", "lleg", "rleg" }
  end
  local live = {}
  for i = 1, #pool do
    if not b.limbs[pool[i]].amputated then live[#live + 1] = pool[i] end
  end
  if #live == 0 then return "thorax" end
  return live[rng:int(1, #live)]
end

--------------------------------------------------------------------- gear

-- Aggregated protection is written here by the inventory module.
function B.armourAt(b, id)
  local g = b.gear or {}
  local a = 0
  if id == "head" then a = (g.head or 0) + (g.face or 0) * 0.5
  elseif id == "thorax" or id == "abdomen" then a = (g.torso or 0)
  elseif id == "larm" or id == "rarm" then a = (g.hands or 0) * 0.6 + (g.torso or 0) * 0.3
  else a = (g.legs or 0) * 0.7 + (g.feet or 0) * 0.4 end
  return a
end

--------------------------------------------------------------------- damage

local function addPain(l, n)
  l.pain = U.clamp(l.pain + n, 0, 100)
end

-- spec fields are documented in data.lua HAZARDS
-- returns a list of { text, colour } style event descriptions
function B.hurt(b, spec, rng, opts)
  opts = opts or {}
  local out = {}
  local id = opts.limb or B.pickTarget(b, spec.target or "any", rng)
  local l = b.limbs[id]
  local meta = D.LIMBS[id]
  local g = b.gear or {}

  local function say(text, colour) out[#out + 1] = { text = text, colour = colour } end

  if spec.fall then
    local h = spec.fall
    local guard = (g.fallGuard or 0)
    local force = math.max(0, h - 1.5) * (1 - guard * 0.5)
    local legTargets = {}
    for _, lid in ipairs(LEG_LIMBS) do
      if not b.limbs[lid].amputated then legTargets[#legTargets + 1] = lid end
    end
    if #legTargets == 0 then legTargets = { "abdomen" } end
    for _, lid in ipairs(legTargets) do
      local ll = b.limbs[lid]
      local skin = force * 2.6 * (1 - B.armourAt(b, lid) / 24)
      local muscle = force * 3.4
      ll.skin = U.clamp(ll.skin - skin, 0, 100)
      ll.muscle = U.clamp(ll.muscle - muscle, 0, 100)
      addPain(ll, force * 4)
      if rng:chance(U.clamp(force * 0.07, 0, 0.85)) then
        B.breakBone(b, lid, rng, out)
      elseif rng:chance(U.clamp(force * 0.06, 0, 0.6)) then
        B.dislocate(b, lid, rng, out)
      end
    end
    if force > 5 and rng:chance(0.4) then
      local core = rng:pick({ "abdomen", "thorax" })
      b.limbs[core].muscle = U.clamp(b.limbs[core].muscle - force * 2, 0, 100)
      addPain(b.limbs[core], force * 2.5)
      b.internal = b.internal + force * 0.012
    end
    if force > 7 and rng:chance(0.3) then
      b.brain = U.clamp(b.brain - force * 0.35, 0, 100)
      say("The landing rings through the skull.", CU.ui.c.bad)
    end
    say(string.format("You come down hard. %.1f metres.", h), CU.ui.c.bad)
    CU.ui.sfx("hurt")
    return out
  end

  local armour = B.armourAt(b, id)
  local mitigate = 1 - U.clamp(armour / 26, 0, 0.62)

  if spec.skin and spec.skin > 0 then
    local amount = spec.skin * mitigate
    if spec.foot and (g.footGuard or 0) > 0 then amount = amount * (1 - g.footGuard) end
    if (g.cutGuard or 0) > 0 and (id == "larm" or id == "rarm") then amount = amount * (1 - g.cutGuard * 0.6) end
    l.skin = U.clamp(l.skin - amount, 0, 100)
  end
  if spec.muscle and spec.muscle > 0 then
    l.muscle = U.clamp(l.muscle - spec.muscle * mitigate, 0, 100)
  end
  if spec.bleed and spec.bleed > 0 then
    l.bleed = l.bleed + spec.bleed * meta.bleedMult * (0.7 + 0.6 * (1 - l.skin / 100))
  end
  if spec.pain and spec.pain > 0 then
    addPain(l, spec.pain * (1 - U.clamp(armour / 40, 0, 0.35)))
  end
  if spec.burn and spec.burn > 0 then
    l.burn = U.clamp(l.burn + spec.burn * mitigate, 0, 100)
    l.skin = U.clamp(l.skin - spec.burn * 0.4, 0, 100)
    addPain(l, spec.burn * 0.8)
  end
  if spec.shrap and spec.shrap > 0 then
    local n = math.floor(spec.shrap * (0.5 + rng:float()) + 0.5)
    if n > 0 then
      l.shrapnel = l.shrapnel + n
      addPain(l, n * 5)
      l.bleed = l.bleed + n * 0.012
      say(n .. " fragment" .. (n == 1 and "" or "s") .. " in the " .. meta.name .. ".", CU.ui.c.warn)
    end
  end
  if spec.infect and spec.infect > 0 then
    local chance = spec.infect * (1.2 - b.immunity / 130)
    if l.disinfect > 0 then chance = chance * 0.15 end
    if rng:chance(U.clamp(chance, 0, 0.95)) then
      l.infection = l.infection + 6 + rng:float() * 10
    end
  end
  if spec.sever and rng:chance(spec.sever) and meta.limb then
    B.amputate(b, id, out, "torn away")
    return out
  end
  if spec.frac and rng:chance(spec.frac) then
    B.breakBone(b, id, rng, out)
  elseif spec.dislo and rng:chance(spec.dislo) then
    B.dislocate(b, id, rng, out)
  end

  -- body-wide riders
  if spec.sick then b.sick = U.clamp(b.sick + spec.sick, 0, 100) end
  if spec.brain then b.brain = U.clamp(b.brain - spec.brain, 0, 100) end
  if spec.cold then b.temp = b.temp - spec.cold * 0.06 end
  if spec.heat then b.temp = b.temp + spec.heat * 0.06 end
  if spec.wet then b.wet = 1 end
  if spec.oil then b.oil = true; b.wet = 1 end
  if spec.fib and rng:chance(spec.fib) then
    b.fib = math.max(b.fib, 40)
    say("Your heart has gone into fibrillation.", CU.ui.c.crit)
  end
  if spec.spore then
    local prot = (b.gear.spore or 0)
    if rng:chance(1 - prot) then
      b.sick = U.clamp(b.sick + 8, 0, 100)
      b.limbs.head.infection = b.limbs.head.infection + 5
    end
  end
  if spec.hold then b.held = 3 end

  if opts.silent ~= true then
    local sev = (spec.pain or 0) + (spec.muscle or 0)
    CU.ui.sfx(sev > 30 and "crack" or "hurt")
  end
  return out, id
end

function B.breakBone(b, id, rng, out)
  local l = b.limbs[id]
  if l.amputated then return end
  local was = l.bone
  l.bone = "fractured"
  l.boneTimer = T.BONE_HEAL_MIN
  l.skin = U.clamp(l.skin - 33, 0, 100)
  l.bleed = l.bleed + rng:range(0, 0.2)
  addPain(l, 100)
  b.adren = math.min(100, b.adren + 80)
  if id == "head" then
    if rng:chance(0.8) then
      b.neck = true
    elseif rng:chance(0.5) then
      b.disfigured = true
    end
  end
  if out then
    out[#out + 1] = { text = "Your " .. D.LIMBS[id].name .. " is broken.",
                      colour = CU.ui.c.crit }
  end
  CU.ui.sfx("crack")
  return was ~= "fractured"
end

function B.dislocate(b, id, rng, out)
  local l = b.limbs[id]
  if l.amputated or l.bone == "fractured" then return end
  l.bone = "dislocated"
  l.boneTimer = T.DISLO_HEAL_MIN
  l.skin = U.clamp(l.skin - 8, 0, 100)
  addPain(l, 48)
  b.adren = math.min(100, b.adren + 40)
  if out then
    out[#out + 1] = { text = "Your " .. D.LIMBS[id].name .. " is out of its joint.",
                      colour = CU.ui.c.bad }
  end
  CU.ui.sfx("crack")
end

function B.amputate(b, id, out, how)
  local l = b.limbs[id]
  if not D.LIMBS[id].limb then return false end
  l.amputated = true
  l.bleed = 1.4
  l.pain = 100
  l.dressing = nil
  l.splint = nil
  b.adren = 100
  if out then
    out[#out + 1] = { text = "Your " .. D.LIMBS[id].name .. " is " .. (how or "gone") .. ".",
                      colour = CU.ui.c.crit }
  end
  CU.ui.sfx("death")
  return true
end

--------------------------------------------------------------------- derived

local function limbFn(b, id)
  local l = b.limbs[id]
  if l.amputated then return 0 end
  local f = l.muscle / 100
  if l.bone == "fractured" then f = f * 0.15 end
  if l.bone == "dislocated" then f = f * 0.5 end
  if l.splint and l.bone ~= "ok" then f = f * 1.5 end
  if l.tourniquet then f = f * 0.55 end
  f = f * (1 - U.clamp(l.pain / 260, 0, 0.5))
  return U.clamp(f, 0, 1)
end
B.limbFunction = limbFn

function B.effectivePain(b)
  local peak, total = 0, 0
  for _, id in ipairs(D.LIMB_ORDER) do
    local l = b.limbs[id]
    local p = l.pain * D.LIMBS[id].painWeight
    if p > peak then peak = p end
    total = total + l.pain
  end
  local raw = U.clamp(peak * 0.62 + total * 0.085, 0, 100)
  local relief = U.clamp(b.opioid / 105, 0, 0.88) + U.clamp(b.adren / 190, 0, 0.5)
  return U.clamp(raw * (1 - U.clamp(relief, 0, 0.93)), 0, 100), raw
end

function B.mobility(b)
  local l = (limbFn(b, "lleg") + limbFn(b, "rleg")) / 2
  local core = limbFn(b, "abdomen") * 0.5 + 0.5
  local m = l * core
  if b.limbs.thorax.bone == "dislocated" then m = m * 0.7 end
  if b.limbs.abdomen.bone == "fractured" then m = m * 0.6 end
  m = m * U.clamp(b.consciousness / 70, 0.15, 1)
  m = m * (1 - U.clamp((B.encumbrance(b) - 1) * 0.5, 0, 0.6))
  if b.temp < 34 then m = m * 0.85 end
  return U.clamp(m, 0.05, 1.15)
end

function B.grip(b, which)
  if which then return limbFn(b, which) end
  return math.max(limbFn(b, "larm"), limbFn(b, "rarm"))
end

function B.handsFree(b)
  local n = 0
  for _, id in ipairs(ARM_LIMBS) do
    local l = b.limbs[id]
    if not l.amputated and l.bone ~= "fractured" and l.muscle >= 20 then n = n + 1 end
  end
  return n
end

function B.steadiness(b, bonus)
  local s = 1.0
  local pain = select(1, B.effectivePain(b))
  s = s - pain / 145
  s = s - (100 - b.consciousness) / 210
  s = s - U.clamp(b.opioid, 0, 100) / 260
  s = s - (100 - b.brain) / 190
  s = s + (b.gear.grip or 0)
  local arms = (limbFn(b, "larm") + limbFn(b, "rarm")) / 2
  s = s - (1 - arms) * 0.35
  if b.temp < 35.2 then s = s - (35.2 - b.temp) * 0.09 end
  if b.sick > 50 then s = s - 0.12 end
  s = s + (bonus or 0)
  s = s + b.traits.int * 0.02
  return U.clamp(s, 0.03, 1)
end

function B.perception(b, lightRadius)
  local p = 0.5 + (lightRadius or 0) * 0.11
  p = p * U.clamp(b.consciousness / 100, 0.2, 1)
  p = p * U.clamp(b.brain / 100, 0.3, 1)
  if b.limbs.head.muscle < 40 then p = p * 0.8 end
  if b.eyeLost then p = p * 0.6 end
  if b.gear.eyeGuard then p = p + 0.05 end
  p = p + b.traits.int * 0.03
  return U.clamp(p, 0.05, 1.1)
end

function B.swingPower(b)
  local best = math.max(limbFn(b, "larm"), limbFn(b, "rarm"))
  local core = 0.5 + limbFn(b, "thorax") * 0.5
  local p = best * core
  if b.neck then p = p * 0.6 end
  if b.limbs.thorax.bone ~= "ok" then p = p * 0.6 end
  p = p * U.clamp(0.55 + b.energy / 180, 0.4, 1.1)
  p = p * (1 + b.traits.str * 0.05)
  p = p * (1 + U.clamp(b.adren, 0, 100) / 320)
  return U.clamp(p, 0.05, 1.6)
end

function B.carryCapacity(b)
  local base = T.CARRY_BASE + (b.gear.carry or 0)
  base = base * (1 + b.traits.str * 0.06)
  local arms = (limbFn(b, "larm") + limbFn(b, "rarm")) / 2
  base = base * (0.55 + 0.45 * arms)
  return base
end

function B.encumbrance(b)
  local cap = B.carryCapacity(b)
  if cap <= 0 then return 3 end
  return (b.load or 0) / cap
end

function B.totalBleed(b)
  local n = b.internal or 0
  for _, id in ipairs(D.LIMB_ORDER) do
    local l = b.limbs[id]
    if l.bleed > 0 then
      local flow = l.bleed
      if l.tourniquet then flow = 0
      elseif l.dressing then flow = flow * (1 - l.dressing.stop) end
      n = n + flow
    end
  end
  return n
end

function B.limbCondition(b, id)
  local l = b.limbs[id]
  if l.amputated then return 0 end
  local f = (l.skin * 0.4 + l.muscle * 0.6) / 100
  if l.bone == "fractured" then f = f * 0.5 end
  if l.bone == "dislocated" then f = f * 0.75 end
  return U.clamp(f, 0, 1)
end

--------------------------------------------------------------------- treatments

local Med = {}
B.med = Med

function Med.applyDressing(b, id, item, rng)
  local l = b.limbs[id]
  local d = item.dressing
  if l.amputated and not d.instant then return false, "There is nothing left to wrap." end
  if d.instant then
    l.bleed = 0
    l.skin = U.clamp(l.skin + (d.skin or 0), 0, 100)
    addPain(l, d.pain or 0)
    b.visc = U.clamp(b.visc + (d.visc or 0), -100, 100)
    return true, "The granules clot the wound. Bleeding stopped."
  end
  l.dressing = { id = item.id, stop = d.stop, absorb = d.absorb, soak = 0, name = item.short }
  l.skin = U.clamp(l.skin + (d.skin or 0), 0, 100)
  l.muscle = U.clamp(l.muscle + (d.muscle or 0), 0, 100)
  addPain(l, d.pain or 0)
  if d.burn then l.burn = U.clamp(l.burn - 40, 0, 100) end
  if d.bone and l.bone ~= "ok" then
    l.boneTimer = math.max(0, l.boneTimer - d.bone * 6)
  end
  if d.dislo and l.bone == "dislocated" then
    l.boneTimer = l.boneTimer * (1 - d.dislo)
    if l.boneTimer <= 0.5 then
      l.bone = "ok"; l.boneTimer = 0
      b.mood = b.mood + 5
      return true, "The joint went back in under the pressure."
    end
  end
  if d.infect and rng:chance(d.infect) then
    l.infection = l.infection + 5
  end
  return true, "Dressing on the " .. D.LIMBS[id].name .. "."
end

function Med.tourniquet(b, id, on)
  local l = b.limbs[id]
  if on then
    if id == "thorax" or id == "abdomen" then
      return false, "There is nothing to tie it around."
    end
    l.tourniquet = { time = 0 }
    if id == "head" then
      b.respArrest = true
      return true, "That is around your neck. You have stopped breathing."
    end
    return true, "Tourniquet on. Bleeding stopped, and the limb is now on a clock."
  else
    l.tourniquet = nil
    if id == "head" then b.respArrest = false end
    return true, "Tourniquet off. The bleeding starts again."
  end
end

function Med.splint(b, id, item, on)
  local l = b.limbs[id]
  if on then
    if l.bone == "ok" then return false, "Nothing in there is broken." end
    l.splint = { mult = item.tool.mult, id = item.id }
    return true, "Splinted."
  else
    l.splint = nil
    return true, "Splint off."
  end
end

-- Manual reduction of a dislocation. Returns success, message, fractured
function Med.reduce(b, id, rng, withWrench)
  local l = b.limbs[id]
  if l.bone ~= "dislocated" then return false, "That joint is not dislocated." end
  local painAdd = withWrench and rng:range(5, 10) or rng:range(15, 24)
  addPain(l, painAdd)
  if rng:chance(withWrench and 0.01 or 0.05) then
    B.breakBone(b, id, rng, nil)
    return false, "You forced it and broke the bone.", true
  end
  local progress = withWrench and rng:range(0.4, 0.7) or rng:range(0.2, 0.45)
  l.boneTimer = l.boneTimer * (1 - progress)
  if l.boneTimer <= 1.5 then
    l.bone = "ok"; l.boneTimer = 0
    b.mood = b.mood + 5
    return true, "The joint is back in place."
  end
  return false, "Closer, but not in yet. Try again."
end

function Med.removeShrapnel(b, id, rng, success, withForceps)
  local l = b.limbs[id]
  if l.shrapnel <= 0 then return false, "No shrapnel left in it." end
  if success then
    l.shrapnel = l.shrapnel - 1
    l.bleed = l.bleed + 0.008
    addPain(l, rng:range(2, 5))
    return true, "Out. " .. (l.shrapnel > 0 and (l.shrapnel .. " to go.") or "That was the last one.")
  else
    addPain(l, rng:range(9, 16))
    l.skin = U.clamp(l.skin - 5, 0, 100)
    l.bleed = l.bleed + 0.02
    if id == "head" and rng:chance(0.8) then
      b.brain = U.clamp(b.brain - rng:range(0, 1), 0, 100)
    end
    return false, "It slips and goes in deeper."
  end
end

function Med.suture(b, id, rng, success)
  local l = b.limbs[id]
  if success then
    l.skin = U.clamp(l.skin + 26, 0, 100)
    l.bleed = l.bleed * 0.25
    addPain(l, 12)
    return true, "The wound is closed."
  end
  addPain(l, 20)
  l.skin = U.clamp(l.skin - 4, 0, 100)
  return false, "The needle tore through. Start again."
end

function Med.weld(b, id)
  local l = b.limbs[id]
  if l.bone == "ok" then return false, "Nothing in there is broken." end
  l.boneTimer = l.boneTimer * (1 - 1 / T.WELDER_DIV)
  l.skin = U.clamp(l.skin - 25, 0, 100)
  l.muscle = U.clamp(l.muscle - 26, 0, 100)
  l.bleed = l.bleed + 0.07
  b.visc = U.clamp(b.visc + 2, -100, 100)
  addPain(l, 30)
  if l.boneTimer <= 1 then
    l.bone = "ok"; l.boneTimer = 0
    b.mood = b.mood + 5
    return true, "The bone is welded. The flesh around it is burnt."
  end
  return true, "Partly welded. It needs another pass."
end

function Med.drug(b, item, rng, doses)
  doses = doses or 1
  local d = item.drug
  local msg = {}
  if d.opioidClear then
    b.opioid = 0
    b.withdrawal = math.min(100, b.withdrawal + 25)
    msg[#msg + 1] = "The opiates are gone. All the pain comes back."
  end
  if d.opioid then
    b.opioid = U.clamp(b.opioid + d.opioid * doses * (1 - b.tolerance / 260), 0, 220)
    b.tolerance = math.min(100, b.tolerance + 3 * doses)
    if b.opioid > 110 then
      b.respArrest = true
      msg[#msg + 1] = "Too much opiate. You have stopped breathing."
      CU.ui.sfx("overdose")
    end
  end
  if d.pain then
    -- distributed as a temporary relief pool rather than deleting pain
    b.painRelief = (b.painRelief or 0) + math.abs(d.pain) * doses
    b.painReliefRamp = d.ramp or 40
  end
  if d.adren then b.adren = U.clamp(b.adren + d.adren * doses, 0, 100) end
  if d.hr then b.hrKick = (b.hrKick or 0) + d.hr * doses end
  if d.blood then
    b.blood = U.clamp(b.blood + d.blood * doses, 0, 7.2)
    if b.blood > 6.1 then msg[#msg + 1] = "Too much volume. Blood pressure is dangerously high." end
  end
  if d.visc then b.visc = U.clamp(b.visc + d.visc * doses, -100, 100) end
  if d.infectionAll then
    for _, id in ipairs(D.LIMB_ORDER) do
      local l = b.limbs[id]
      l.infection = U.clamp(l.infection + d.infectionAll * doses, 0, 100)
    end
    msg[#msg + 1] = "The antibiotics take hold. Infection is falling."
  end
  if d.immunity then b.immunity = U.clamp(b.immunity + d.immunity, 0, 130) end
  if d.sick then b.sick = U.clamp(b.sick + d.sick * doses, 0, 100) end
  if d.energy then b.energy = U.clamp(b.energy + d.energy * doses, 0, 100) end
  if d.resp then b.respMod = (b.respMod or 0) + d.resp * doses end
  if d.crash then b.crash = (b.crash or 0) + d.crash end
  if d.cardiac then
    if b.arrest or b.fib > 0 then
      if rng:chance(0.45) then
        b.arrest = false; b.arrestTime = 0; b.fib = 0
        msg[#msg + 1] = "The heart restarts."
      else
        msg[#msg + 1] = "No effect. Try again, or use the paddles."
      end
    end
  end
  if d.infectChance and rng:chance(d.infectChance) then
    local id = rng:pick(D.LIMB_ORDER)
    b.limbs[id].infection = b.limbs[id].infection + 14
    msg[#msg + 1] = "That blood was carrying an infection."
  end
  if d.sleep then b.sleepy = 600 end
  -- overdose bookkeeping
  if d.via == "oral" and doses >= 3 then
    b.sick = U.clamp(b.sick + 20, 0, 100)
    msg[#msg + 1] = "That was more than one dose should be."
  end
  if #msg == 0 then msg[1] = "Taken." end
  return table.concat(msg, " ")
end

function Med.disinfect(b, id, seconds)
  local l = b.limbs[id]
  l.disinfect = math.max(l.disinfect, seconds)
  l.infection = U.clamp(l.infection - 12, 0, 100)
  addPain(l, 7)
  return true, "Disinfected. That wound will not go bad for a while."
end

function Med.defib(b, rng)
  if not (b.arrest or b.fib > 0) then
    b.fib = math.max(b.fib, 25)
    return false, "There was a rhythm. Now there is not."
  end
  if rng:chance(0.6) then
    b.arrest = false; b.arrestTime = 0; b.fib = 0
    b.limbs.thorax.burn = U.clamp(b.limbs.thorax.burn + 8, 0, 100)
    return true, "The heart restarts."
  end
  b.limbs.thorax.burn = U.clamp(b.limbs.thorax.burn + 10, 0, 100)
  return false, "No response. The capacitor is refilling."
end

function Med.drain(b)
  if b.hemothorax <= 1 then return false, "There is no blood in the chest cavity." end
  local drained = b.hemothorax
  b.hemothorax = 0
  b.limbs.thorax.skin = U.clamp(b.limbs.thorax.skin - 6, 0, 100)
  addPain(b.limbs.thorax, 22)
  return true, string.format("Chest drained. Breathing improves. (%.0f cleared)", drained)
end

--------------------------------------------------------------------- moodles

local function push(list, code, label, colour, sev)
  list[#list + 1] = { code = code, label = label, colour = colour, sev = sev or 1 }
end

function B.moodles(b)
  local c = CU.ui.c
  local out = {}
  local bleed = B.totalBleed(b)
  if bleed > 0.35 then push(out, "BLD", "catastrophic bleeding", c.crit, 3)
  elseif bleed > 0.12 then push(out, "bld", "heavy bleeding", c.blood, 2)
  elseif bleed > 0.018 then push(out, "bld", "bleeding", c.blood, 1) end
  if b.internal > 0.04 then push(out, "INT", "internal bleeding", c.crit, 3) end
  if b.hemothorax > 4 then push(out, "HTX", "hemothorax", c.crit, 3) end
  if b.blood < 3.4 then push(out, "HYP", "hypovolemic", c.crit, 3)
  elseif b.blood < 4.3 then push(out, "hyp", "blood loss", c.bad, 2) end
  if b.blood > 6.0 then push(out, "VOL", "hypervolemic", c.bad, 2) end
  if b.spo2 < 70 then push(out, "O2!", "critical hypoxemia", c.crit, 3)
  elseif b.spo2 < 88 then push(out, "o2", "hypoxemia", c.bad, 2) end
  if b.arrest then push(out, "ARR", "cardiac arrest", c.crit, 4) end
  if b.fib > 0 then push(out, "FIB", "fibrillation", c.crit, 3) end
  if b.respArrest then push(out, "RSP", "respiratory arrest", c.crit, 3) end
  if b.hr > 155 then push(out, "TAC", "tachycardia", c.bad, 2)
  elseif b.hr < 45 and not b.arrest then push(out, "BRA", "bradycardia", c.bad, 2) end
  if b.bp < 72 then push(out, "BP-", "severe hypotension", c.crit, 3)
  elseif b.bp < 88 then push(out, "bp-", "hypotension", c.bad, 2)
  elseif b.bp > 165 then push(out, "BP+", "hypertension", c.bad, 2) end
  local pain = select(1, B.effectivePain(b))
  if pain > 78 then push(out, "PAI", "agony", c.crit, 3)
  elseif pain > 52 then push(out, "pai", "severe pain", c.bad, 2)
  elseif pain > 26 then push(out, "pai", "in pain", c.warn, 1) end
  if b.opioid > 110 then push(out, "OD!", "opioid overdose", c.crit, 4)
  elseif b.opioid > 55 then push(out, "OPI", "heavily drugged", c.drug, 2)
  elseif b.opioid > 12 then push(out, "opi", "opiated", c.drug, 1) end
  if b.withdrawal > 45 then push(out, "WDR", "withdrawal", c.drug, 2) end
  if b.adren > 40 then push(out, "adr", "adrenaline", c.gold, 1) end
  if b.sepsis > 50 then push(out, "SEP", "septic shock", c.crit, 4)
  elseif b.sepsis > 12 then push(out, "sep", "sepsis", c.infect, 3) end
  local inf = 0
  for _, id in ipairs(D.LIMB_ORDER) do
    if b.limbs[id].revealed then inf = inf + 1 end
  end
  if inf > 0 then push(out, "INF", inf .. " infected", c.infect, 2) end
  if b.brain < 30 then push(out, "COM", "comatose", c.crit, 4)
  elseif b.brain < 60 then push(out, "NEU", "neurological damage", c.crit, 3)
  elseif b.brain < 80 then push(out, "neu", "neurological damage", c.bad, 2)
  elseif b.brain < 95 then push(out, "cog", "cognitive impairment", c.warn, 1) end
  if b.temp < 32 then push(out, "FRZ", "freezing to death", c.crit, 4)
  elseif b.temp < 35 then push(out, "col", "hypothermia", c.cold, 2)
  elseif b.temp > 40.5 then push(out, "HOT", "heatstroke", c.crit, 3)
  elseif b.temp > 38.4 then push(out, "fev", "fever", c.hot, 2) end
  if b.wet > 0.4 then push(out, "wet", "soaked", c.cold, 1) end
  if b.sick > 55 then push(out, "SIC", "sick", c.infect, 2)
  elseif b.sick > 22 then push(out, "sic", "queasy", c.warn, 1) end
  if b.hunger < 12 then push(out, "STV", "starving", c.crit, 3)
  elseif b.hunger < 34 then push(out, "hun", "hungry", c.warn, 1) end
  if b.thirst < 12 then push(out, "DEH", "dehydrated", c.crit, 3)
  elseif b.thirst < 34 then push(out, "thi", "thirsty", c.warn, 1) end
  if b.energy < 18 then push(out, "EXH", "exhausted", c.bad, 2)
  elseif b.energy < 40 then push(out, "tir", "tired", c.warn, 1) end
  if b.consciousness < T.CONSCIOUS_OUT then push(out, "OUT", "unconscious", c.crit, 4)
  elseif b.consciousness < 45 then push(out, "daz", "dazed", c.bad, 2) end
  local enc = B.encumbrance(b)
  if enc > 1.25 then push(out, "LOD", "overloaded", c.bad, 2)
  elseif enc > 1 then push(out, "lod", "heavy", c.warn, 1) end
  for _, id in ipairs(D.LIMB_ORDER) do
    if b.limbs[id].tourniquet then push(out, "TQ", "tourniquet", c.warn, 2); break end
  end
  if b.embolism then push(out, "EMB", "pulmonary embolism", c.crit, 4) end
  if b.trapped then push(out, "TRP", "leg trap", c.crit, 4) end
  if b.eyeLost then push(out, "EYE", "one eye", c.bad, 2) end
  if b.limbs.head.bone == "dislocated" then push(out, "JAW", "jaw out", c.bad, 2) end
  if b.amputations and b.amputations > 0 then push(out, "AMP", "amputated", c.crit, 3) end
  table.sort(out, function(x, y) return x.sev > y.sev end)
  return out
end

--------------------------------------------------------------------- the tick

local function stepOnce(b, dt, env, rng, events)
  local m = dt / 60   -- minutes
  local c = CU.ui.c

  ------------------------------------------------ bleeding and clotting
  local bleed = B.totalBleed(b)
  if bleed > 0 then
    b.blood = math.max(0, b.blood - bleed * m)
    b.bloodLost = (b.bloodLost or 0) + bleed * m
  end

  local clotBase = T.CLOT_BASE * (1 + b.visc / 100) * (1 + b.traits.res * 0.08)
  if b.blood < 3.5 then clotBase = clotBase * 0.75 end
  for _, id in ipairs(D.LIMB_ORDER) do
    local l = b.limbs[id]
    if l.bleed > 0 then
      local rate = clotBase
      if l.shrapnel > 0 then rate = rate * 0.15 end
      if l.dressing then rate = rate * (1 + l.dressing.stop * 2.2) end
      if l.tourniquet then rate = rate * 1.6 end
      if l.amputated and not l.tourniquet then rate = rate * 0.25 end
      l.bleed = math.max(0, l.bleed - rate * dt)
    end
    -- dressings soak and fail
    if l.dressing then
      local through = l.bleed * (1 - l.dressing.stop) + l.bleed * l.dressing.stop
      l.dressing.soak = l.dressing.soak + through * m
      if l.dressing.absorb > 0 and l.dressing.soak >= l.dressing.absorb then
        events[#events + 1] = { text = "The dressing on your " .. D.LIMBS[id].name ..
          " has soaked through.", colour = c.bad }
        l.dressing = nil
      end
    end
    -- tourniquet damage
    if l.tourniquet then
      l.tourniquet.time = l.tourniquet.time + dt
      addPain(l, 8 * m)
      if l.tourniquet.time > 360 then
        l.muscle = U.clamp(l.muscle - 0.9 * m, 0, 100)
        if not l.tqWarn and l.tourniquet.time > 400 then
          l.tqWarn = true
          events[#events + 1] = { text = "The limb under the tourniquet is dying. Take it off or lose it.",
            colour = c.crit }
        end
      end
    end
  end

  ------------------------------------------------ internal bleeding / hemothorax
  if b.limbs.abdomen.muscle < 22 or b.limbs.thorax.muscle < 22 then
    b.internal = b.internal + 0.0016 * m
  end
  if b.internal > 0 then
    b.internal = math.max(0, b.internal - 0.0006 * (1 + b.visc / 100) * m)
    if b.internal >= 0.0427 then
      b.hemothorax = b.hemothorax + (b.internal / 0.0427) * 2.64 * m
      addPain(b.limbs.thorax, b.internal * 0.25 * m * 60)
    end
  end
  if b.hemothorax > 0 then
    b.hemothorax = math.max(0, b.hemothorax - 0.1 * m)
  end

  ------------------------------------------------ bones
  for _, id in ipairs(D.LIMB_ORDER) do
    local l = b.limbs[id]
    if l.bone ~= "ok" and l.boneTimer > 0 then
      local rate = m
      if l.splint then rate = rate * l.splint.mult end
      if b.hunger < 20 then rate = rate * 0.5 end
      l.boneTimer = l.boneTimer - rate
      if l.boneTimer <= 0 then
        local was = l.bone
        l.bone = "ok"; l.boneTimer = 0
        b.mood = math.min(100, b.mood + 5)
        events[#events + 1] = { text = "Your " .. D.LIMBS[id].name .. " has healed.", colour = c.ok }
      end
    end
    -- bone injury caps muscle
    if l.bone ~= "ok" and l.muscle > 50 then l.muscle = 50 end
  end

  ------------------------------------------------ infection
  local totalInf = 0
  local feverSources = 0
  for _, id in ipairs(D.LIMB_ORDER) do
    local l = b.limbs[id]
    if l.disinfect > 0 then l.disinfect = l.disinfect - dt end
    if not l.amputated then
      local wound = (100 - l.skin) / 100
      if l.shrapnel > 0 then wound = wound + 0.15 * l.shrapnel end
      local immFactor = U.clamp((160 - b.immunity) / 60, 0.35, 2.5)
      if l.disinfect > 0 then
        -- antiseptic holds it and pushes it back
        l.infection = math.max(0, l.infection - 0.4 * m)
      elseif wound > 0.08 then
        local rate = T.INFECT_RATE * wound * immFactor * (1 + (env.dirty or 0))
        l.infection = U.clamp(l.infection + rate * m, 0, 100)
      elseif l.infection < T.INFECT_REVEAL then
        -- a closed wound sheds a small contamination on its own
        l.infection = math.max(0, l.infection - 0.3 * m)
      end
      if l.infection >= T.INFECT_REVEAL and not l.revealed then
        l.revealed = true
        events[#events + 1] = { text = "The wound on your " .. D.LIMBS[id].name ..
          " is infected.", colour = c.infect }
      end
      if l.infection >= 75 then
        l.skin = math.max(0, l.skin - 0.9 * m)
      end
      if l.revealed then feverSources = feverSources + 1 end
      totalInf = totalInf + l.infection
    end
  end
  if totalInf > T.SEPSIS_AT then
    b.sepsis = U.clamp(b.sepsis + (totalInf - T.SEPSIS_AT) * 0.02 * m, 0, 100)
  else
    b.sepsis = math.max(0, b.sepsis - 0.6 * m)
  end
  b.immunity = U.clamp(b.immunity + 0.25 * m
    - (b.sepsis > 0 and 0.5 * m or 0), 10, 130)

  ------------------------------------------------ pain
  local relief = 0
  if b.painRelief and b.painRelief > 0 then
    local shed = math.min(b.painRelief, (b.painReliefRamp or 40) * m)
    relief = shed
    b.painRelief = b.painRelief - shed * 0.35
  end
  for _, id in ipairs(D.LIMB_ORDER) do
    local l = b.limbs[id]
    local floor = 0
    if not l.amputated then
      floor = (100 - l.skin) / T.SKIN_PAIN_DIV
        + (100 - l.muscle) / T.MUSCLE_PAIN_DIV
        + (l.bone == "fractured" and 34 or l.bone == "dislocated" and 20 or 0)
        + l.shrapnel * 4.5 + l.burn * 0.45 + l.infection * 0.22
      if l.splint and l.bone ~= "ok" then floor = floor - 8 end
      if l.tourniquet then floor = floor + 18 end
    else
      floor = 30
    end
    floor = U.clamp(floor, 0, 100)
    local decay = T.PAIN_DECAY * (1 + (l.chill > 0 and 1.5 or 0)) * m
      + relief * 0.12 * D.LIMBS[id].painWeight
    if l.pain > floor then
      l.pain = math.max(floor, l.pain - decay)
    else
      l.pain = math.min(floor, l.pain + T.PAIN_DECAY * 1.4 * m)
    end
    if l.chill > 0 then l.chill = l.chill - dt end
    if l.warm > 0 then l.warm = l.warm - dt end
    if l.burn > 0 then l.burn = math.max(0, l.burn - 0.5 * m) end
  end

  ------------------------------------------------ drugs
  b.opioid = math.max(0, b.opioid - 0.55 * m * (1 + b.traits.res * 0.05))
  b.adren = math.max(0, b.adren - 4.5 * m)
  b.tolerance = math.max(0, b.tolerance - 0.05 * m)
  if b.tolerance > 25 and b.opioid < 4 then
    b.withdrawal = U.clamp(b.withdrawal + 0.5 * m, 0, 100)
  else
    b.withdrawal = math.max(0, b.withdrawal - 1.2 * m)
  end
  if b.withdrawal > 40 then
    b.mood = math.max(0, b.mood - 0.8 * m)
    b.sick = U.clamp(b.sick + 0.5 * m, 0, 100)
  end
  if b.held and b.held > 0 then b.held = math.max(0, b.held - m) end
  if b.trapped then
    b.trapped.timer = b.trapped.timer - dt
    local l = b.limbs[b.trapped.limb]
    if l then
      l.bleed = math.max(l.bleed, 0.09)
      addPain(l, 3 * m)
    end
    if b.trapped.timer <= 0 then b.trapped = nil end
  end
  if b.hrKick then b.hrKick = b.hrKick * (1 - 0.35 * m) end
  if b.respMod then b.respMod = b.respMod * (1 - 0.25 * m) end
  if b.crash and b.crash > 0 then
    b.crash = math.max(0, b.crash - 0.02 * m)
    b.energy = math.max(0, b.energy - b.crash * 2 * m)
  end
  if b.opioid > 110 then
    b.respArrest = true
    b.brain = math.max(0, b.brain - 0.6 * m)
    b.temp = b.temp - 0.02 * m
  elseif b.opioid < 90 and b.respArrest and not b.arrest then
    local stillArrested = false
    for _, id in ipairs(D.LIMB_ORDER) do
      if b.limbs[id].tourniquet and id == "head" then stillArrested = true end
    end
    if not stillArrested then b.respArrest = false end
  end

  ------------------------------------------------ oxygen and circulation
  -- Saturation holds up until volume gets genuinely low, then falls off a cliff.
  local maxO2 = 100
  if b.blood < 4.5 then
    if b.blood >= T.BLOOD_CAP_FLOOR then
      maxO2 = U.remap(b.blood, T.BLOOD_CAP_FLOOR, 4.5, 30, 100)
    else
      maxO2 = U.remap(b.blood, 1.0, T.BLOOD_CAP_FLOOR, 0, 30)
    end
  end
  maxO2 = maxO2 - b.hemothorax * 0.3 - b.sepsis * 0.22
  if math.abs(b.visc) > 40 then maxO2 = maxO2 - (math.abs(b.visc) - 40) * 0.4 end
  if b.limbs.thorax.muscle < 30 then maxO2 = maxO2 - (30 - b.limbs.thorax.muscle) * 0.9 end
  maxO2 = U.clamp(maxO2, 0, 100)
  b.maxO2 = maxO2

  local resp = T.RESP_BASE + (env.exertion or 0) * 8 - b.opioid * 0.16
    - b.hemothorax * 0.125 + (b.respMod or 0)
  if b.limbs.thorax.muscle <= 0 then resp = 0 end
  if b.respArrest or b.arrest then resp = 0 end
  b.resp = U.clamp(resp, 0, 44)

  if b.resp > 12.5 and not b.arrest then
    b.spo2 = U.approach(b.spo2, maxO2, 26 * m)
  else
    b.spo2 = math.max(0, b.spo2 - 36 * m)
  end
  if b.spo2 > maxO2 then b.spo2 = U.approach(b.spo2, maxO2, 40 * m) end

  local fever = math.max(0, b.temp - 37.2)
  local hr = T.HR_BASE + b.adren * 0.55 + select(1, B.effectivePain(b)) * 0.28
    + (T.BLOOD_FULL - b.blood) * 16 + (env.exertion or 0) * 26
    - b.opioid * 0.3 + fever * 6 + (b.hrKick or 0) + b.sepsis * 0.3
  if b.temp < 34 then hr = hr - (34 - b.temp) * 6 end
  b.hr = U.clamp(hr, 0, 235)
  if b.arrest then b.hr = 0 end

  b.bp = U.clamp(T.BP_BASE + b.adren * 0.25 - (T.BLOOD_FULL - b.blood) * 13
    - b.sepsis * 0.5 - b.opioid * 0.22 + (b.visc > 60 and (b.visc - 60) * 0.4 or 0), 0, 210)

  -- fibrillation and arrest
  if b.hr > 195 and not b.arrest then b.fib = math.min(100, b.fib + 6 * m) end
  if math.abs(b.visc) > 88 then
    if rng:chance(0.02 * m * 60) then
      b.embolism = true
      events[#events + 1] = { text = "A clot has reached your lung.", colour = c.crit }
    end
  elseif math.abs(b.visc) < 50 then
    b.embolism = false
  end
  if b.embolism then
    b.limbs.thorax.muscle = math.max(0, b.limbs.thorax.muscle - 36 * m)
  end
  if b.fib > 0 then
    b.fib = b.fib + 3 * m
    b.spo2 = math.max(0, b.spo2 - 14 * m)
    if b.fib > 100 and not b.arrest then
      b.arrest = true
      events[#events + 1] = { text = "The heart stops.", colour = c.crit }
      CU.ui.sfx("alarm")
    end
  end
  if b.blood < 1.6 and not b.arrest and rng:chance(0.03 * m * 60) then
    b.arrest = true
    events[#events + 1] = { text = "You have lost too much blood. Your heart has stopped.", colour = c.crit }
  end
  if b.arrest then
    b.arrestTime = b.arrestTime + dt
    b.brain = math.max(0, b.brain - 1.6 * m)
  end
  b.visc = U.approach(b.visc, 0, 3 * m)

  ------------------------------------------------ brain and consciousness
  if b.spo2 < 55 then
    b.brain = math.max(0, b.brain - (55 - b.spo2) * 0.06 * m)
  elseif not b.arrest then
    b.brain = math.min(100, b.brain + T.BRAIN_REGEN * m * (b.energy > 25 and 1 or 0.4))
  end
  if b.temp > 40.5 then b.brain = math.max(0, b.brain - (b.temp - 40.5) * 1.4 * m) end


  local o2cap
  if b.spo2 >= 90 then o2cap = 100
  elseif b.spo2 >= 50 then o2cap = U.remap(b.spo2, 50, 90, 22, 100)
  else o2cap = U.remap(b.spo2, 0, 50, 0, 22) end
  local painCap = 100 - math.max(0, select(1, B.effectivePain(b)) - 68) * 2.4
  local opioidCap = 100 - math.max(0, b.opioid - 60) * 1.4
  local energyCap = b.energy < 12 and (40 + b.energy * 4) or 100
  local cap = math.min(b.brain, o2cap, painCap, opioidCap, energyCap, 100)
  if b.sleepy and b.sleepy > 0 then
    b.sleepy = b.sleepy - dt
    cap = math.min(cap, 30)
  end
  if cap < b.consciousness then
    b.consciousness = math.max(cap, b.consciousness - 70 * m)
  else
    b.consciousness = math.min(cap, b.consciousness + 34 * m)
  end

  ------------------------------------------------ temperature
  local ambient = (env.temp or 20)
  local warmth = (b.gear.warmth or 0) + (env.heat or 0)
  local effective = ambient + warmth * 1.6 + (env.exertion or 0) * 6
  if b.wet > 0.2 then effective = effective - 9 * b.wet end
  if b.oil then effective = effective - 3 end
  local target = U.clamp(28 + (effective - 4) * 0.28, 20, 45)
  local drift = (target - b.temp) * 0.012 * m
  b.temp = b.temp + drift
  if feverSources > 0 and b.temp < 40.5 then
    b.temp = math.min(40.5, b.temp + 0.08 * feverSources * m)
  end
  if b.sepsis > 20 then b.temp = math.min(41.5, b.temp + 0.02 * m) end
  b.wet = math.max(0, b.wet - 0.02 * m * (b.temp > 20 and 1.4 or 0.7))
  if b.wet <= 0 then b.oil = false end
  if b.temp < 35 then
    b.energy = math.max(0, b.energy - (35 - b.temp) * 0.4 * m)
  end
  if b.temp < 28 then
    b.consciousness = math.max(0, b.consciousness - 8 * m)
    b.hr = math.max(0, b.hr - 20)
  end
  if b.temp > 41.5 then b.sick = U.clamp(b.sick + 3 * m, 0, 100) end

  ------------------------------------------------ needs
  local burn = 1 + (env.exertion or 0) * 1.4
  b.hunger = U.clamp(b.hunger - T.HUNGER_RATE * burn * m, 0, 120)
  b.thirst = U.clamp(b.thirst - T.THIRST_RATE * burn * (b.temp > 38 and 1.5 or 1) * m, 0, 120)
  if env.resting then
    b.energy = U.clamp(b.energy + 3.2 * m, 0, 100)
  else
    b.energy = U.clamp(b.energy - T.ENERGY_RATE * burn * m, 0, 100)
  end
  if b.hunger <= 0 then
    for _, id in ipairs(D.LIMB_ORDER) do
      b.limbs[id].muscle = math.max(0, b.limbs[id].muscle - 0.5 * m)
    end
  end
  if b.thirst <= 0 then b.visc = U.clamp(b.visc + 1.6 * m, -100, 100) end
  if b.sick > 0 then b.sick = math.max(0, b.sick - 0.5 * m) end
  if b.sick > 70 and rng:chance(0.02 * m * 60) then
    b.hunger = math.max(0, b.hunger - 18)
    b.consciousness = math.max(0, b.consciousness - 10)
    events[#events + 1] = { text = "You throw up.", colour = c.warn }
  end

  ------------------------------------------------ natural repair
  if b.hunger > 15 and b.blood > 3 then
    for _, id in ipairs(D.LIMB_ORDER) do
      local l = b.limbs[id]
      if not l.amputated and l.infection < T.INFECT_REVEAL and l.shrapnel == 0 then
        local rate = (env.resting and 2.2 or 0.55) * m * (1 + b.traits.res * 0.1)
        if l.skin < 100 then l.skin = math.min(100, l.skin + rate * 0.7) end
        local cap = (l.bone ~= "ok") and 50 or 100
        if l.muscle < cap then l.muscle = math.min(cap, l.muscle + rate * 0.35) end
      end
    end
  end

  ------------------------------------------------ mood
  local moodTarget = 62 - select(1, B.effectivePain(b)) * 0.3 - (100 - b.hunger) * 0.08
    - (100 - b.thirst) * 0.06 - b.sick * 0.15 - (100 - b.brain) * 0.2
    + (b.gear.mood or 0)
  b.mood = U.approach(b.mood, U.clamp(moodTarget, 0, 100), 3 * m)

  ------------------------------------------------ death
  if not b.dead then
    if b.blood <= T.BLOOD_DEAD then
      b.dead = true; b.cause = "exsanguination"
    elseif b.brain <= 0 then
      b.dead = true; b.cause = "loss of brain function"
    elseif b.arrest and b.arrestTime > T.ARREST_GRACE then
      b.dead = true; b.cause = "cardiac arrest"
    elseif b.temp < 24 then
      b.dead = true; b.cause = "hypothermia"
    elseif b.temp > 43 then
      b.dead = true; b.cause = "hyperthermia"
    end
    if b.dead then
      events[#events + 1] = { text = "", colour = c.crit }
      CU.ui.sfx("death")
    end
  end
end

-- Public tick. dt in seconds, sliced internally.
function B.tick(b, dt, env, rng)
  env = env or {}
  local events = {}
  if b.dead then return events end
  local remaining = dt
  local slice = (dt > 120) and 10 or 2
  local guard = 0
  while remaining > 0 and not b.dead and guard < 4000 do
    local step = math.min(slice, remaining)
    stepOnce(b, step, env, rng, events)
    remaining = remaining - step
    guard = guard + 1
  end
  -- collapse duplicate messages
  local seen, out = {}, {}
  for i = 1, #events do
    local key = events[i].text
    if key ~= "" and not seen[key] then
      seen[key] = true
      out[#out + 1] = events[i]
    end
  end
  return out
end

function B.status(b)
  if b.dead then return "deceased" end
  if b.consciousness < T.CONSCIOUS_OUT then return "unconscious" end
  return "ambulatory"
end

CU.body = B
return B

end
]=])

put("lib/fall.lua", [=[
-- WRITE-OFF / lib/fall.lua
-- Falling is the main way this game hurts you. It only counts if you descended.

return function(CU)

local U = CU.util
local D = CU.data
local F = {}

-- How far you can drop onto bare stone before anything happens at all.
F.FREE_DROP = 3

--[[
  Distance and surface decide everything.

    effective = metres * (1 - cushion) * hardness, minus what your boots absorb

  A moss bed takes about three quarters of the impact out of a fall. Broken rock
  takes none of it and turns most of what is left into punctures rather than
  crush injuries. Bare stone is the baseline.

  Rough shape of the curve, landing on bare stone with no gear:

     under 3 m   nothing
       3 - 12 m  bruising, a little pain
      12 - 30 m  torn muscle, a joint may come out
      30 - 60 m  a joint almost certainly, a fracture becomes likely
     60 - 150 m  legs break, arms often follow
    150 - 400 m  multiple fractures, internal bleeding, head injury
        400 m +  usually fatal, not always
]]

function F.effective(metres, surface, gear)
  local eff = metres * (1 - (surface.cushion or 0)) * (surface.hard or 0.9)
  local boots = (gear and gear.fallGuard or 0)
  eff = eff * (1 - U.clamp(boots, 0, 0.55))
  return math.max(0, eff)
end

-- Predict what a drop from here would cost, for the ledge-peek readout.
function F.forecast(metres, surface, gear)
  local eff = F.effective(metres, surface, gear)
  if eff < F.FREE_DROP then return "safe", eff end
  if eff < 12 then return "bruising", eff end
  if eff < 30 then return "torn muscle", eff end
  if eff < 60 then return "joints and bones", eff end
  if eff < 150 then return "broken legs", eff end
  if eff < 400 then return "severe, multiple", eff end
  return "probably fatal", eff
end

local function chance(rng, p) return rng:chance(U.clamp(p, 0, 0.97)) end

-- Resolve a landing. Returns a list of { text, colour } lines in plain language.
function F.land(body, metres, surfaceChar, rng)
  local B = CU.body
  local Tl = CU.tiles
  local c = CU.ui.c
  local out = {}
  local function say(t, col) out[#out + 1] = { text = t, colour = col or c.text } end

  local surface = Tl.impact(surfaceChar)
  local gear = body.gear or {}
  local eff = F.effective(metres, surface, gear)
  local sharp = surface.sharp or 0.1

  body.lastFall = { metres = metres, surface = surface.name, effective = eff }

  if metres < 1 then return out end

  if eff < F.FREE_DROP then
    if metres >= 4 then
      say(string.format("You drop %d m onto %s. No damage.", math.floor(metres), surface.name), c.dim)
    end
    return out
  end

  say(string.format("You fall %d m and land on %s.", math.floor(metres), surface.name),
      eff > 30 and c.crit or c.warn)
  CU.ui.sfx(eff > 30 and "crack" or "hurt")

  -- which legs take it
  local legs = {}
  for _, id in ipairs({ "lleg", "rleg" }) do
    if not body.limbs[id].amputated then legs[#legs + 1] = id end
  end
  if #legs == 0 then legs = { "abdomen" } end

  -- the first leg down takes more than the second
  local share = { 1.0, 0.78 }
  for i, id in ipairs(legs) do
    local s = share[i] or 0.6
    local hit = {
      muscle = eff * 0.85 * s * (1 - sharp * 0.45),
      skin   = eff * 0.50 * s * (0.30 + sharp),
      bleed  = eff * 0.0055 * s * sharp * 2.2,
      pain   = eff * 1.30 * s,
    }
    B.hurt(body, hit, rng, { limb = id, silent = true })

    local l = body.limbs[id]
    local fracP = ((eff * s) - 18) / 90 * (1 - sharp * 0.4)
    local disloP = ((eff * s) - 7) / 45
    if chance(rng, fracP) then
      B.breakBone(body, id, rng, out)
    elseif chance(rng, disloP) then
      B.dislocate(body, id, rng, out)
    end
    if sharp > 0.5 and chance(rng, (eff * s - 10) / 140) then
      l.shrapnel = l.shrapnel + rng:int(1, 2)
      say("Rock fragments are lodged in your " .. D.LIMBS[id].name .. ".", c.warn)
    end
  end

  -- you put your hands out
  if chance(rng, (eff - 32) / 190) then
    local arm = rng:pick({ "larm", "rarm" })
    if not body.limbs[arm].amputated then
      B.hurt(body, {
        muscle = eff * 0.35, skin = eff * 0.28 * (0.3 + sharp),
        bleed = eff * 0.002 * sharp, pain = eff * 0.7,
      }, rng, { limb = arm, silent = true })
      if chance(rng, (eff - 45) / 150) then
        B.breakBone(body, arm, rng, out)
      elseif chance(rng, (eff - 25) / 90) then
        B.dislocate(body, arm, rng, out)
      end
    end
  end

  -- the trunk folds
  if eff > 25 then
    B.hurt(body, { muscle = eff * 0.22, pain = eff * 0.4 }, rng,
      { limb = "abdomen", silent = true })
  end
  local internalP = (eff - 45) / 300
  if chance(rng, internalP) then
    body.internal = body.internal + eff * 0.00035
    say("Something has torn inside you.", c.crit)
  end

  -- the head, last, and only from a real height
  local headP = (eff - 60) / 280 * (1 - (gear.skullGuard or 0))
  if chance(rng, headP) then
    B.hurt(body, {
      muscle = eff * 0.18, skin = eff * 0.2 * (0.3 + sharp), pain = eff * 0.5,
    }, rng, { limb = "head", silent = true })
    body.brain = U.clamp(body.brain - eff * 0.06, 0, 100)
    say("Your head hit the ground.", c.crit)
  end

  body.adren = math.min(100, body.adren + math.min(70, eff * 0.9))
  return out
end

CU.fall = F
return F

end
]=])

put("lib/inv.lua", [=[
-- WRITE-OFF / lib/inv.lua
-- Carrying, wearing, wielding, burning fuel, and making things out of scrap.

return function(CU)

local U = CU.util
local D = CU.data
local Inv = {}

function Inv.new()
  return {
    slots = {},
    wear = {},          -- slot -> entry
    weapon = nil,       -- entry
    light = nil,        -- entry
    flask = { amount = 0, clean = false },
  }
end

local function def(entry) return D.ITEMS[entry.id] end
Inv.def = def

--------------------------------------------------------------------- stacks

function Inv.add(inv, id, n, meta)
  local it = D.ITEMS[id]
  if not it then return 0 end
  n = n or 1
  local added = 0
  if it.stack > 1 and not meta then
    for i = 1, #inv.slots do
      local e = inv.slots[i]
      if e.id == id and not e.equipped and e.n < it.stack then
        local room = it.stack - e.n
        local take = math.min(room, n - added)
        e.n = e.n + take
        added = added + take
        if added >= n then return added end
      end
    end
  end
  while added < n do
    local take = math.min(it.stack, n - added)
    local e = { id = id, n = take }
    if it.tool and it.tool.charges then e.charges = it.tool.charges end
    if it.tool and it.tool.uses then e.uses = it.tool.uses end
    if it.light and it.light.fuel then e.fuel = it.light.fuel end
    if it.misc and it.misc.cell then e.cell = it.misc.cell end
    if meta then for k, v in pairs(meta) do e[k] = v end end
    inv.slots[#inv.slots + 1] = e
    added = added + take
  end
  return added
end

function Inv.count(inv, id)
  local n = 0
  for i = 1, #inv.slots do
    if inv.slots[i].id == id then n = n + inv.slots[i].n end
  end
  return n
end

function Inv.remove(inv, id, n)
  n = n or 1
  local removed = 0
  for i = #inv.slots, 1, -1 do
    local e = inv.slots[i]
    if e.id == id and not e.equipped then
      local take = math.min(e.n, n - removed)
      e.n = e.n - take
      removed = removed + take
      if e.n <= 0 then
        if inv.weapon == e then inv.weapon = nil end
        if inv.light == e then inv.light = nil end
        table.remove(inv.slots, i)
      end
      if removed >= n then return removed end
    end
  end
  return removed
end

function Inv.removeEntry(inv, entry, n)
  n = n or 1
  entry.n = entry.n - n
  if entry.n <= 0 then
    for i = #inv.slots, 1, -1 do
      if inv.slots[i] == entry then table.remove(inv.slots, i) end
    end
    if inv.weapon == entry then inv.weapon = nil end
    if inv.light == entry then inv.light = nil end
    for slot, e in pairs(inv.wear) do
      if e == entry then inv.wear[slot] = nil end
    end
  end
end

function Inv.entries(inv, filter)
  local out = {}
  for i = 1, #inv.slots do
    local e = inv.slots[i]
    local it = def(e)
    if it and (not filter or filter(e, it)) then out[#out + 1] = e end
  end
  return out
end

function Inv.mass(inv)
  local m = 0
  for i = 1, #inv.slots do
    local it = def(inv.slots[i])
    if it then m = m + it.mass * inv.slots[i].n end
  end
  m = m + (inv.flask.amount or 0)
  return m
end

function Inv.value(inv)
  local v = 0
  for i = 1, #inv.slots do
    local it = def(inv.slots[i])
    if it then v = v + it.value * inv.slots[i].n end
  end
  return v
end

--------------------------------------------------------------------- wearing

function Inv.wearableSlot(it)
  return it.wear and it.wear.slot or nil
end

function Inv.equipWear(inv, entry)
  local it = def(entry)
  local slot = Inv.wearableSlot(it)
  if not slot then return false, "Not something you wear." end
  if inv.wear[slot] then
    inv.wear[slot].equipped = nil
  end
  entry.equipped = true
  inv.wear[slot] = entry
  return true, it.name .. " on."
end

function Inv.unequipWear(inv, slot)
  local e = inv.wear[slot]
  if not e then return false end
  e.equipped = nil
  inv.wear[slot] = nil
  return true
end

function Inv.equipWeapon(inv, entry, body)
  local it = def(entry)
  if not it.weapon then return false, "That is not a weapon." end
  local hands = CU.body.handsFree(body)
  if (it.weapon.hands or 1) > hands then
    return false, "You need more working hands for that."
  end
  inv.weapon = entry
  return true, it.name .. " in hand."
end

function Inv.equipLight(inv, entry)
  local it = def(entry)
  if not it.light and not (it.wear and it.wear.lightRadius) then
    return false, "That does not give off light."
  end
  inv.light = entry
  entry.lit = true
  return true, it.name .. " lit."
end

--------------------------------------------------------------------- gear

function Inv.updateGear(inv, body)
  local g = {
    head = 0, face = 0, torso = 0, hands = 0, legs = 0, feet = 0,
    warmth = 0, carry = 0, rad = 0, spore = 0, grip = 0,
    fallGuard = 0, footGuard = 0, skullGuard = 0, cutGuard = 0, eyeGuard = 0,
    mood = 0, encumber = 0, pump = false, lightRadius = 0,
  }
  for slot, e in pairs(inv.wear) do
    local it = def(e)
    if it and it.wear then
      local w = it.wear
      g[slot] = (g[slot] or 0) + (w.armour or 0)
      g.warmth = g.warmth + (w.warmth or 0)
      g.carry = g.carry + (w.carry or 0)
      g.rad = math.min(0.92, g.rad + (w.rad or 0))
      g.spore = math.min(0.95, g.spore + (w.spore or 0))
      g.grip = g.grip + (w.grip or 0)
      g.fallGuard = math.min(0.8, g.fallGuard + (w.fallGuard or 0))
      g.footGuard = math.min(0.95, g.footGuard + (w.footGuard or 0))
      g.skullGuard = math.min(0.8, g.skullGuard + (w.skullGuard or 0))
      g.cutGuard = math.min(0.85, g.cutGuard + (w.cutGuard or 0))
      g.eyeGuard = math.min(0.9, g.eyeGuard + (w.eyeGuard or 0))
      g.mood = g.mood + (w.mood or 0)
      g.encumber = g.encumber + (w.encumber or 0)
      if w.pump then g.pump = true end
    end
  end
  body.gear = g
  body.load = Inv.mass(inv) + g.encumber * 2
  return g
end

--------------------------------------------------------------------- light

function Inv.lightRadius(inv)
  local r = 0.35   -- what the eyes manage unaided down here
  local e = inv.light
  if e and e.lit then
    local it = def(e)
    local spec = it.light or (it.wear and it.wear)
    if spec then
      local ok = true
      if spec.needsCell and (e.cell or 0) <= 0 then ok = false end
      if spec.fuel and (e.fuel or 0) <= 0 then ok = false end
      if ok then r = math.max(r, spec.radius or spec.lightRadius or 0) end
    end
  end
  for _, we in pairs(inv.wear) do
    local it = def(we)
    if it and it.wear and it.wear.lightRadius and (we.cell or 0) > 0 then
      r = math.max(r, it.wear.lightRadius)
    end
  end
  return r
end

function Inv.revealsInfection(inv)
  local e = inv.light
  if e and e.lit then
    local it = def(e)
    if it.light and it.light.reveal then return true end
  end
  return false
end

function Inv.tickLights(inv, dt)
  local msgs = {}
  local function drainEntry(e, spec)
    if not e or not spec then return end
    if spec.fuel and e.fuel then
      e.fuel = e.fuel - dt
      if e.fuel <= 0 then
        e.fuel = 0
        e.lit = false
        msgs[#msgs + 1] = def(e).name .. " has burnt out."
        if inv.light == e then
          inv.light = nil
          Inv.removeEntry(inv, e, e.n)
        end
      end
    elseif spec.needsCell and e.cell then
      e.cell = e.cell - (spec.drain or 1) * dt / 60
      if e.cell <= 0 then
        e.cell = 0
        msgs[#msgs + 1] = def(e).name .. " is out of charge. It needs a cell."
      end
    end
  end
  local e = inv.light
  if e and e.lit then
    local it = def(e)
    drainEntry(e, it.light)
  end
  for _, we in pairs(inv.wear) do
    local it = def(we)
    if it and it.wear and it.wear.lightRadius then drainEntry(we, it.wear) end
  end
  return msgs
end

function Inv.reload(inv, entry)
  local it = def(entry)
  local spec = it.light or (it.wear and it.wear)
  if not spec or not spec.needsCell then return false, "That does not take a cell." end
  if Inv.count(inv, "cell") <= 0 then return false, "No cells." end
  Inv.remove(inv, "cell", 1)
  entry.cell = 100
  return true, "New cell fitted."
end

--------------------------------------------------------------------- crafting

function Inv.canCraft(inv, recipe)
  for id, n in pairs(recipe.need) do
    if Inv.count(inv, id) < n then return false end
  end
  return true
end

function Inv.craft(inv, recipe, body)
  if not Inv.canCraft(inv, recipe) then return false, "You do not have the parts." end
  if recipe.int and body and body.traits.int < recipe.int then
    return false, "You cannot work out how it goes together."
  end
  for id, n in pairs(recipe.need) do Inv.remove(inv, id, n) end
  Inv.add(inv, recipe.out, recipe.n or 1)
  return true, "Made: " .. D.ITEMS[recipe.out].name ..
    ((recipe.n or 1) > 1 and (" x" .. recipe.n) or "")
end

function Inv.availableRecipes(inv, body)
  local out = {}
  for i = 1, #D.RECIPES do
    local r = D.RECIPES[i]
    local can = Inv.canCraft(inv, r)
    local smart = (not r.int) or (body and body.traits.int >= r.int)
    out[#out + 1] = { recipe = r, can = can and smart, missing = not can, dumb = not smart }
  end
  return out
end

--------------------------------------------------------------------- water

function Inv.drink(inv, body, amount)
  amount = amount or 0.25
  if inv.flask.amount <= 0 then return false, "The flask is empty." end
  local take = math.min(amount, inv.flask.amount)
  inv.flask.amount = inv.flask.amount - take
  body.thirst = U.clamp(body.thirst + take * 100, 0, 120)
  if not inv.flask.clean then
    body.sick = U.clamp(body.sick + take * 40, 0, 100)
    return true, "Dirty water. That may make you sick."
  end
  return true, "Clean water."
end

function Inv.fill(inv, clean)
  if Inv.count(inv, "water_flask") <= 0 then return false, "You need a flask." end
  inv.flask.amount = 0.75
  inv.flask.clean = clean and true or false
  return true, clean and "Flask filled with clean water." or "Flask filled. The water is not clean."
end

CU.inv = Inv
return Inv

end
]=])

put("lib/mapgen.lua", [=[
-- WRITE-OFF / lib/mapgen.lua
-- Builds one stratum as a 2D side-on map. Ropes are slow and safe. Drops are not.

return function(CU)

local U = CU.util
local D = CU.data
local Tl = CU.tiles
local M = {}

M.W = 80        -- tiles across  (160 m)
M.H = 150       -- tiles down    (300 m)

--------------------------------------------------------------------- loot

function M.rollLoot(pool, tier, rng, count)
  local candidates = {}
  local list = D.LOOT[pool] or D.LOOT.general
  for i = 1, #list do
    local e = list[i]
    if (e.tier or 1) <= tier then
      local w = e.w * (1 + math.max(0, tier - (e.tier or 1)) * -0.06)
      if w > 0.4 then candidates[#candidates + 1] = { w = w, e = e } end
    end
  end
  local out = {}
  for _ = 1, count do
    local sel = rng:weighted(candidates)
    if sel then
      local e = sel.e
      out[#out + 1] = { id = e.id, n = e.n and rng:int(e.n[1], e.n[2]) or 1 }
    end
  end
  return out
end

--------------------------------------------------------------------- access

function M.get(map, x, y)
  if x < 1 or x > map.w or y < 1 or y > map.h then return "#" end
  return map.rows[y]:sub(x, x)
end

function M.set(map, x, y, ch)
  if x < 1 or x > map.w or y < 1 or y > map.h then return end
  local r = map.rows[y]
  map.rows[y] = r:sub(1, x - 1) .. ch .. r:sub(x + 1)
end

function M.key(x, y) return x .. "," .. y end

function M.prop(map, x, y) return map.props[M.key(x, y)] end

--------------------------------------------------------------------- blood

-- Blood pools on the floor under you. It stays where it fell, so a trail of it
-- is both a warning and a record of where you have already been.
M.BLOOD_CAP = 600

function M.addBlood(map, x, y, amount)
  if amount <= 0 then return end
  map.blood = map.blood or {}
  -- prefer the floor under the feet, so it reads as a pool on the ground
  local ty = y
  if Tl.isFloor(M.get(map, x, y + 1)) then ty = y + 1 end
  local k = M.key(x, ty)
  map.blood[k] = math.min(0.5, (map.blood[k] or 0) + amount)
  map.bloodCount = (map.bloodCount or 0) + ((map.blood[k] == amount) and 1 or 0)

  -- keep the table from growing without limit on a very long run
  if (map.bloodCount or 0) > M.BLOOD_CAP then
    local worstKey, worstVal = nil, 1e9
    for kk, vv in pairs(map.blood) do
      if vv < worstVal then worstKey, worstVal = kk, vv end
    end
    if worstKey then map.blood[worstKey] = nil; map.bloodCount = map.bloodCount - 1 end
  end
end

-- A splash, for landings and fights. Spreads over a couple of tiles.
function M.splashBlood(map, x, y, amount, rng)
  M.addBlood(map, x, y, amount)
  for _ = 1, 2 do
    local dx = rng and rng:int(-1, 1) or 0
    if Tl.passable(M.get(map, x + dx, y)) then
      M.addBlood(map, x + dx, y, amount * 0.5)
    end
  end
end

function M.bloodAt(map, x, y)
  return map.blood and map.blood[M.key(x, y)] or nil
end

function M.seen(map, x, y)
  local row = map.seen[y]
  return row and row[x] or false
end

-- Blood you have left on the floor. It stays, so it doubles as a trail back.
function M.addBlood(map, x, y, amount)
  if x < 1 or x > map.w or y < 1 or y > map.h then return end
  map.blood = map.blood or {}
  local k = M.key(x, y)
  local v = (map.blood[k] or 0) + amount
  if v <= 0 then map.blood[k] = nil else map.blood[k] = math.min(4, v) end
end

function M.bloodAt(map, x, y)
  if not map.blood then return 0 end
  return map.blood[M.key(x, y)] or 0
end

-- Progress into a tile you are mining. Cleared when the tile breaks.
function M.digAt(map, x, y)
  if not map.dug then return 0 end
  return map.dug[M.key(x, y)] or 0
end

function M.setDig(map, x, y, n)
  map.dug = map.dug or {}
  map.dug[M.key(x, y)] = n
end

function M.clearDig(map, x, y)
  if map.dug then map.dug[M.key(x, y)] = nil end
end

function M.markSeen(map, x, y)
  map.seen[y] = map.seen[y] or {}
  map.seen[y][x] = true
end

--------------------------------------------------------------------- pods

--[[
  A pod is a sealed shell bolted onto a gallery floor. Doors both sides at body
  height, so it never blocks the way through. Two kinds:

    supply : lockers and boxes nobody has been back for
    trade  : somebody is still living in it, and they will deal

  Both have a thermostat and a decontamination shower, which is the only way to
  clear infection out of every limb at once without spending antibiotics.
]]

function M.podAt(map, x, y)
  for _, p in ipairs(map.pods or {}) do
    if x >= p.x1 and x <= p.x2 and y >= p.y1 and y <= p.y2 then return p end
  end
  return nil
end

function M.insidePod(map, x, y)
  local p = M.podAt(map, x, y)
  if p and x > p.x1 and x < p.x2 and y > p.y1 and y < p.y2 then return p end
  return nil
end

local function spanClear(map, gy, x1, x2)
  for x = x1, x2 do
    for y = gy - 4, gy do
      local ch = M.get(map, x, y)
      local d = Tl.get(ch)
      if d.climb or d.shaft or d.hatch or d.prop or d.fixture then return false end
    end
    -- there has to be a floor under the whole length
    if not Tl.isFloor(M.get(map, x, gy)) then return false end
    -- and headroom for the shell
    for y = gy - 4, gy - 1 do
      if not Tl.passable(M.get(map, x, y)) then return false end
    end
  end
  return true
end

local function makeTrader(map, rng)
  local def = D.TRADERS[rng:int(1, #D.TRADERS)]
  local tier = map.strat.lootTier
  local stock = {}
  local seen = {}
  for _, id in ipairs(def.stock) do
    if D.ITEMS[id] and not seen[id] then
      seen[id] = true
      stock[#stock + 1] = { id = id, n = rng:int(1, 3) }
    end
  end
  for _ = 1, rng:int(3, 5) do
    local roll = M.rollLoot(rng:chance(0.5) and "medical" or "general", tier, rng, 1)[1]
    if roll and not seen[roll.id] then
      seen[roll.id] = true
      stock[#stock + 1] = { id = roll.id, n = roll.n }
    end
  end
  return {
    id = def.id, name = def.name,
    attitude = 46 + rng:int(0, 12),
    scrip = 140 + tier * 70 + rng:int(0, 120),
    stock = stock,
    hostile = false, hugs = 0, haggles = 0, threats = 0, met = false,
  }
end

function M.buildPod(map, rng, gallery, kind)
  local width = rng:int(9, 13)
  local gy = gallery.y
  local tries = 0
  local x1
  while tries < 30 do
    tries = tries + 1
    local candidate = rng:int(gallery.x1 + 1, math.max(gallery.x1 + 1, gallery.x2 - width))
    if candidate + width <= gallery.x2 - 1 and spanClear(map, gy, candidate, candidate + width) then
      x1 = candidate
      break
    end
  end
  if not x1 then return nil end
  local x2 = x1 + width

  -- shell. three tiles of headroom inside, so a person fits standing up.
  for x = x1, x2 do
    M.set(map, x, gy - 4, "B")
    M.set(map, x, gy, "B")
  end
  M.set(map, x1, gy - 3, "B")
  M.set(map, x2, gy - 3, "B")
  for x = x1 + 1, x2 - 1 do M.set(map, x, gy - 3, " ") end
  for y = gy - 2, gy - 1 do
    M.set(map, x1, y, "D")
    M.set(map, x2, y, "D")
    for x = x1 + 1, x2 - 1 do M.set(map, x, y, " ") end
  end

  local pod = { x1 = x1, y1 = gy - 4, x2 = x2, y2 = gy,
                kind = kind, temp = 18, showers = 2 }

  -- what is inside, laid out along the standing row
  local slots = {}
  for x = x1 + 2, x2 - 2 do slots[#slots + 1] = x end
  rng:shuffle(slots)
  local function place(ch)
    local x = table.remove(slots)
    if not x then return nil end
    M.set(map, x, gy - 1, ch)
    return x
  end

  place("Z")            -- thermostat
  place("Y")            -- shower
  place("P")            -- bunk
  place("C")            -- charge post for your lights

  if kind == "trade" then
    pod.trader = makeTrader(map, rng)
    pod.traderX = place("T")
    local c = place("l")
    if c then
      map.props[M.key(c, gy - 1)] = {
        type = "locker", name = "the trader's locker", time = 40, rolls = 2,
        searched = false, emptied = false, pool = "general", locked = true,
      }
    end
  else
    local kinds = { { "m", "medbox", "medical" }, { "l", "locker", "general" },
                    { "t", "toolchest", "tools" }, { "h", "cache", "general" },
                    { "c", "crate", "general" } }
    rng:shuffle(kinds)
    for i = 1, rng:int(3, 4) do
      local k = kinds[i]
      if k then
        local x = place(k[1])
        if x then
          map.props[M.key(x, gy - 1)] = {
            type = k[2], name = "a " .. k[2], time = 45, rolls = 3,
            searched = false, emptied = false, pool = k[3],
          }
        end
      end
    end
  end

  map.pods[#map.pods + 1] = pod
  return pod
end

local function placePods(map, rng)
  map.pods = map.pods or {}
  local chance = 0.34 + map.index * 0.012
  if map.index == 1 then chance = 0.7 end       -- so the first run meets one
  if not rng:chance(chance) then return end
  local order = {}
  for i = 2, #map.galleries - 1 do order[#order + 1] = i end
  rng:shuffle(order)
  local kind = rng:chance(0.55) and "trade" or "supply"
  for _, gi in ipairs(order) do
    if M.buildPod(map, rng, map.galleries[gi], kind) then return end
  end
end

--------------------------------------------------------------------- generation

local FLOOR_MIX = {
  { w = 58, ch = "#" },
  { w = 14, ch = "%" },
  { w = 10, ch = "o" },
  { w = 8,  ch = '"' },
  { w = 6,  ch = "^" },
}

local function pickFloor(rng, strat)
  local pool = {}
  for _, e in ipairs(FLOOR_MIX) do
    local w = e.w
    if strat.floorBias and strat.floorBias[e.ch] then w = w * strat.floorBias[e.ch] end
    pool[#pool + 1] = { w = w, ch = e.ch }
  end
  return rng:weighted(pool).ch
end

function M.generate(index, rng)
  local strat = D.stratum(index)
  local w, h = M.W, M.H
  local grid = {}
  for y = 1, h do
    local row = {}
    for x = 1, w do row[x] = "#" end
    grid[y] = row
  end

  local function put(x, y, ch)
    if x >= 1 and x <= w and y >= 1 and y <= h then grid[y][x] = ch end
  end
  local function at(x, y)
    if x < 1 or x > w or y < 1 or y > h then return "#" end
    return grid[y][x]
  end

  -- 1. stack of galleries down the map
  local galleries = {}
  local y = 7
  local lastX1, lastX2 = 6, w - 5
  while y < h - 8 do
    local span = rng:int(30, 58)
    local x1 = U.clamp(lastX1 + rng:int(-16, 16), 3, w - span - 3)
    local x2 = math.min(w - 3, x1 + span)
    -- keep an overlap with the gallery above so a connector can always be placed
    if x2 < lastX1 + 8 then x1 = lastX1; x2 = math.min(w - 3, x1 + span) end
    if x1 > lastX2 - 8 then x2 = lastX2; x1 = math.max(3, x2 - span) end

    local headroom = rng:int(4, 6)
    for x = x1, x2 do
      for hy = y - headroom, y - 1 do put(x, hy, " ") end
    end
    -- floor material in runs, so surfaces are readable rather than noise
    local x = x1
    while x <= x2 do
      local run = rng:int(3, 11)
      local ch = pickFloor(rng, strat)
      for i = 0, run - 1 do
        if x + i <= x2 then put(x + i, y, ch) end
      end
      x = x + run
    end
    -- water sits in a carved basin so it has depth
    if rng:chance(0.35) then
      local px = rng:int(x1 + 2, math.max(x1 + 2, x2 - 8))
      local pw = rng:int(4, 9)
      local pd = rng:int(1, 2)
      for i = 0, pw - 1 do
        for dy = 0, pd - 1 do put(px + i, y - dy, "~") end
        put(px + i, y + 1, "#")
      end
    end

    galleries[#galleries + 1] = { y = y, x1 = x1, x2 = x2, head = headroom }
    lastX1, lastX2 = x1, x2
    y = y + rng:int(9, 15)
  end

  local spawnXGuess = math.floor((galleries[1].x1 + galleries[1].x2) / 2)

  -- 2. connectors. every gallery keeps a clean walking corridor from the point
  --    you arrive at to the rope you leave by, so there is always a safe route
  --    down. open drops are cut outside that corridor, where taking one is a
  --    choice rather than the only option.
  local corridor = {}
  local arriveX = spawnXGuess
  for i = 1, #galleries - 1 do
    local a, b = galleries[i], galleries[i + 1]
    local lo = math.max(a.x1 + 1, b.x1 + 1)
    local hi = math.min(a.x2 - 1, b.x2 - 1)
    if lo > hi then
      lo = math.max(a.x1 + 1, b.x1 + 1)
      hi = math.max(lo, math.min(a.x2 - 1, b.x2 - 1))
    end
    local ropeX = rng:int(lo, math.max(lo, hi))
    for cy = a.y, b.y - 1 do put(ropeX, cy, "|") end

    local c1 = math.min(arriveX, ropeX) - 1
    local c2 = math.max(arriveX, ropeX) + 1
    corridor[i] = { x1 = c1, x2 = c2 }
    a.corridor = corridor[i]
    a.ropeX = ropeX

    -- open drops, only outside the corridor
    -- wide holes now, so the whole span has to clear the corridor, not just
    -- its left edge. otherwise a five tile drop eats the safe route.
    local drops = rng:int(0, 2)
    for _ = 1, drops do
      local wide = rng:int(3, 5)
      local slots = {}
      for x = a.x1 + 1, a.x2 - wide do
        if (x + wide - 1) < c1 - 1 or x > c2 + 1 then slots[#slots + 1] = x end
      end
      if #slots == 0 then break end
      local dx = slots[rng:int(1, #slots)]
      for k = 0, wide - 1 do
        for cy = a.y, b.y - 1 do put(dx + k, cy, " ") end
      end
    end

    arriveX = ropeX
  end
  galleries[#galleries].corridor = { x1 = arriveX - 1, x2 = arriveX + 1 }

  -- 3. one long shaft, sometimes. this is where a real fall comes from.
  --    it is never cut through a gallery's safe corridor.
  if #galleries > 5 and rng:chance(0.7) then
    local start = rng:int(1, math.max(1, #galleries - 4))
    local depth = rng:int(3, math.min(7, #galleries - start))
    local top, bot = galleries[start], galleries[start + depth]
    local lo = math.max(top.x1 + 2, bot.x1 + 2)
    local hi = math.min(top.x2 - 3, bot.x2 - 3)
    local choices = {}
    for x = lo, hi do
      local clear = true
      for gi = start, start + depth do
        local co = galleries[gi].corridor
        if co and x >= co.x1 - 1 and x <= co.x2 + 2 then clear = false end
      end
      if clear then choices[#choices + 1] = x end
    end
    if #choices > 0 then
      local sx = choices[rng:int(1, #choices)]
      for cy = top.y, bot.y - 1 do
        put(sx, cy, " ")
        put(sx + 1, cy, " ")
      end
      local floorCh = rng:weighted({
        { w = 4, ch = "#" }, { w = 3, ch = "^" }, { w = 2, ch = "o" },
        { w = 3, ch = '"' }, { w = 2, ch = "~" },
      }).ch
      put(sx, bot.y, floorCh)
      put(sx + 1, bot.y, floorCh)
      if floorCh == "~" then
        put(sx, bot.y - 1, "~"); put(sx + 1, bot.y - 1, "~")
        put(sx, bot.y + 1, "#"); put(sx + 1, bot.y + 1, "#")
      end
    end
  end

  -- 4. the way out, at the bottom
  local last = galleries[#galleries]
  local co = last.corridor or { x1 = last.x1 + 2, x2 = last.x2 - 2 }
  local exitX = U.clamp(co.x1 + rng:int(0, math.max(0, co.x2 - co.x1)),
                        last.x1 + 1, last.x2 - 1)
  put(exitX, last.y, index >= 11 and "A" or "V")

  -- 5. spawn, at the top
  local first = galleries[1]
  local spawnX = spawnXGuess
  for x = spawnX - 1, spawnX + 1 do
    if at(x, first.y) == "^" or at(x, first.y) == "~" then put(x, first.y, "#") end
    for hy = first.y - 3, first.y - 1 do put(x, hy, " ") end
  end

  -- freeze rows to strings
  local rows = {}
  for gy = 1, h do rows[gy] = table.concat(grid[gy]) end

  local map = {
    index = index, strat = strat, w = w, h = h, rows = rows,
    props = {}, seen = {}, entities = {}, blood = {}, dug = {}, pods = {}, blood = {}, bloodCount = 0,
    galleries = galleries,
    spawn = { x = spawnX, y = first.y - 1 },
    exit = { x = exitX, y = last.y },
    depthTop = (index - 1) * (M.H * Tl.METRES_PER_TILE),
  }

  map.pods = {}
  placePods(map, rng)
  M.populate(map, rng)
  return map
end

--------------------------------------------------------------------- contents

local PROP_CHARS = {
  { w = 22, ch = "d", kind = "debris" },
  { w = 16, ch = "c", kind = "crate" },
  { w = 12, ch = "b", kind = "corpse" },
  { w = 12, ch = "l", kind = "locker" },
  { w = 10, ch = "t", kind = "toolchest" },
  { w = 10, ch = "m", kind = "medbox" },
  { w = 8,  ch = "g", kind = "growth" },
  { w = 4,  ch = "h", kind = "cache" },
}

local CONTAINER_BY_KIND = {}

function M.populate(map, rng)
  local strat = map.strat
  for kind, _ in pairs({}) do end
  if not CONTAINER_BY_KIND.debris then
    for _, c in ipairs(D.CONTAINERS) do CONTAINER_BY_KIND[c.id] = c end
  end

  local function standable(x, y)
    -- room for a two tile body, with a floor under it
    return Tl.passable(M.get(map, x, y)) and Tl.passable(M.get(map, x, y - 1))
      and Tl.isFloor(M.get(map, x, y + 1))
      and not Tl.isClimb(M.get(map, x, y))
      and M.get(map, x, y) ~= "V" and M.get(map, x, y) ~= "A"
      and not M.podAt(map, x, y)
  end

  local spots = {}
  for _, g in ipairs(map.galleries) do
    for x = g.x1 + 1, g.x2 - 1 do
      if standable(x, g.y - 1) then spots[#spots + 1] = { x = x, y = g.y - 1, g = g } end
    end
  end
  rng:shuffle(spots)

  local n = math.min(#spots, 14 + rng:int(0, 8) + math.floor(map.index / 2))
  local placed = 0
  local medPlaced = false
  local i = 1
  while placed < n and i <= #spots do
    local s = spots[i]; i = i + 1
    if M.get(map, s.x, s.y) == " " then
      local sel = rng:weighted(PROP_CHARS)
      local def = CONTAINER_BY_KIND[sel.kind]
      if def then
        M.set(map, s.x, s.y, sel.ch)
        map.props[M.key(s.x, s.y)] = {
          type = def.id, name = def.name, time = def.time, rolls = def.rolls,
          locked = def.locked or false, searched = false, emptied = false,
          corpse = def.corpse or false,
          pool = def.medical and "medical" or def.tools and "tools"
                 or def.forage and "forage" or def.junk and "junk" or "general",
        }
        if def.medical then medPlaced = true end
        placed = placed + 1
      end
    end
  end
  if not medPlaced and i <= #spots then
    local s = spots[i]
    local def = CONTAINER_BY_KIND.medbox
    M.set(map, s.x, s.y, "m")
    map.props[M.key(s.x, s.y)] = {
      type = "medbox", name = def.name, time = def.time, rolls = def.rolls,
      searched = false, emptied = false, pool = "medical",
    }
  end

  -- fixtures
  local FIXTURES = { { w = 5, ch = "S" }, { w = 4, ch = "W" }, { w = 3, ch = "C" },
                     { w = 3, ch = "P" }, { w = 3, ch = "F" }, { w = 4, ch = "n" } }
  local fixtures = 2 + rng:int(0, 3)
  for _ = 1, fixtures do
    if i > #spots then break end
    local s = spots[i]; i = i + 1
    if M.get(map, s.x, s.y) == " " then
      local ch = rng:weighted(FIXTURES).ch
      M.set(map, s.x, s.y, ch)
      if ch == "n" then
        map.props[M.key(s.x, s.y)] = { type = "note", doc = rng:int(1, #D.DOCS) }
      end
    end
  end

  -- the cargo sits on the floor of stratum ten
  if map.index == 10 and i <= #spots then
    local s = spots[i]; i = i + 1
    M.set(map, s.x, s.y, "X")
  end

  -- traps. left behind by people who wanted this level to themselves.
  local trapPool = { { w = 5, ch = "I" }, { w = 3, ch = "K" }, { w = 3, ch = "J" } }
  local traps = 1 + rng:int(0, 2) + math.floor(map.index / 3)
  for _ = 1, traps do
    if i > #spots then break end
    local s2 = spots[i]; i = i + 1
    if M.get(map, s2.x, s2.y) == " " and not M.podAt(map, s2.x, s2.y) then
      M.set(map, s2.x, s2.y, rng:weighted(trapPool).ch)
    end
  end

  -- creatures
  if #strat.creatures > 0 then
    local count = 3 + rng:int(0, 3) + math.floor(map.index / 3)
    for _ = 1, count do
      if i > #spots then break end
      local s = spots[i]; i = i + 1
      if M.get(map, s.x, s.y) == " " then
        local pick = rng:weighted(strat.creatures)
        if pick then
          map.entities[#map.entities + 1] = {
            id = pick.id, x = s.x, y = s.y, hp = nil, awake = false, cooldown = 0,
          }
        end
      end
    end
  end
end

--------------------------------------------------------------------- queries

-- Depth in metres of a row.
function M.depthAt(map, y)
  return map.depthTop + (y - 1) * Tl.METRES_PER_TILE
end

function M.entityAt(map, x, y)
  for _, e in ipairs(map.entities) do
    if e.x == x and e.y == y and not e.dead then return e end
  end
  return nil
end

CU.mapgen = M
return M

end
]=])

put("lib/phys.lua", [=[
-- WRITE-OFF / lib/phys.lua
-- Walking, climbing, jumping, and the part where the floor stops being there.
-- The character is one tile wide and two tiles tall. The drawn figure is three
-- tall; the head only takes up screen space, not physical space.

return function(CU)

local U = CU.util
local D = CU.data
local Tl = CU.tiles
local M = CU.mapgen
local P = {}

local MPT = Tl.METRES_PER_TILE

P.BODY_H = 2          -- collision height in tiles, feet included

-- animation timing. these are the numbers to change if the jump feels wrong.
P.AIR_FRAME  = 0.11   -- seconds per cell of a jump arc
P.APEX_HANG  = 0.20   -- extra beat at the top of a jump
P.FALL_FRAME = 0.05   -- seconds per tile of a fall
P.SLIDE_FRAME = 0.07  -- seconds per tile while sliding a wall

--------------------------------------------------------------------- fitting

-- Is there room for the whole body with its feet at (x, y)?
function P.fits(map, x, y)
  if x < 1 or x > map.w or y < 2 or y > map.h then return false end
  for i = 0, P.BODY_H - 1 do
    if not Tl.passable(M.get(map, x, y - i)) then return false end
  end
  return true
end

function P.supported(map, x, y)
  if Tl.isClimb(M.get(map, x, y)) then return true end
  if Tl.isLiquid(M.get(map, x, y)) then return true end
  local below = M.get(map, x, y + 1)
  return Tl.isFloor(below) or Tl.isClimb(below) or Tl.isLiquid(below)
end

function P.canStand(map, x, y)
  return P.fits(map, x, y) and P.supported(map, x, y)
end

-- A wall you could get a hand on, on the given side.
function P.wallAt(map, x, y, dx)
  return Tl.isSolid(M.get(map, x + dx, y)) or Tl.isSolid(M.get(map, x + dx, y - 1))
end

--------------------------------------------------------------------- falling

-- How far a drop from (x, y) goes, and what is at the bottom.
function P.scanDrop(map, x, y)
  local tiles = 0
  local cy = y
  while cy < map.h do
    local below = M.get(map, x, cy + 1)
    local d = Tl.get(below)
    if d.shaft or d.hatch then return tiles, below, cy + 1, true end
    if Tl.isLiquid(below) then return tiles, below, cy + 1, false end
    if not Tl.passable(below) or Tl.isFloor(below) then return tiles, below, cy, false end
    if Tl.isClimb(below) then return tiles, below, cy, false end
    cy = cy + 1
    tiles = tiles + 1
  end
  return tiles, "#", map.h, false
end

local function waterDepth(map, x, y)
  local n, cy = 0, y
  while Tl.isLiquid(M.get(map, x, cy)) and n < 12 do n = n + 1; cy = cy + 1 end
  return n
end

--[[
  Gravity, one tile at a time, so the player can react on the way down.

  Pushing into a wall while falling catches it and turns the fall into a slide.
  Sliding wipes out the speed you had built up, which is the point: a slide is
  how you survive a shaft you should not have stepped into. It costs skin off
  your hands and arms, and it needs arms that still work.
]]
function P.settle(g, opts)
  opts = opts or {}
  local map = g.map
  local metres = 0
  local slidTiles = 0
  local guard = 0
  g.sliding = false

  while not P.supported(map, g.x, g.y) and guard < 2000 and not g.over do
    guard = guard + 1

    -- straight into the shaft below
    local under = M.get(map, g.x, g.y + 1)
    local ud = Tl.get(under)
    if ud.shaft or ud.hatch then
      g:say("You drop into the shaft.", CU.ui.c.crit)
      metres = metres + 20
      g.sliding = false
      if not g:descendTo(g.stratumIndex + 1, true) then return metres end
      map = g.map
      if P.supported(map, g.x, g.y) then
        P.resolveLanding(g, metres, M.get(map, g.x, g.y + 1))
        return metres
      end
    end

    -- which way is the player pushing, and is there a wall there
    local dir = 0
    if not (CU.ui.headless or opts.instant) then
      dir = CU.ui.pollDirection(g.sliding and P.SLIDE_FRAME or P.FALL_FRAME)
    elseif opts.slideDir then
      dir = opts.slideDir
    end

    local gripping = false
    local drift = 0
    if dir ~= 0 then
      if P.wallAt(map, g.x, g.y, dir) then
        local grip = CU.body.grip(g.body)
        if grip >= 0.25 then
          gripping = true
        elseif not g.slideFailed then
          g.slideFailed = true
          g:say("You get a hand to the wall and it does not hold.", CU.ui.c.bad)
        end
      elseif P.fits(map, g.x + dir, g.y) then
        drift = dir            -- steering in the air, the same as any platformer
      end
    end
    if drift ~= 0 then
      g.x = g.x + drift
      g.facing = drift
    end

    if gripping then
      if not g.sliding then
        g.sliding = true
        g:say("You catch the wall and start sliding.", CU.ui.c.gold)
        CU.ui.sfx("slide")
      end
      metres = 0                       -- the slide takes the speed out of it
      slidTiles = slidTiles + 1
      local glove = (g.body.gear.cutGuard or 0)
      local arm = (dir < 0) and "larm" or "rarm"
      if not g.body.limbs[arm].amputated then
        CU.body.hurt(g.body, {
          skin = 0.9 * (1 - glove * 0.7),
          pain = 1.4 * (1 - glove * 0.5),
          bleed = 0.0016 * (1 - glove * 0.8),
        }, g.rng, { limb = arm, silent = true })
      end
      g.body.energy = math.max(0, g.body.energy - 0.35)
      g:advance(1, { exertion = 0.9 })
    else
      if g.sliding then
        g.sliding = false
        g:say("The wall runs out.", CU.ui.c.warn)
      end
      metres = metres + MPT
    end

    g.y = g.y + 1
    if CU.body.totalBleed(g.body) > 0.05 then M.addBlood(map, g.x, g.y, 1) end
    local frame = opts.onFrame or g.onFrame
    if frame then frame(g) end
    if g.body.dead then g:endRun(g.body.cause); return metres end
  end

  if slidTiles > 0 then
    g:say(string.format("Slid %d m down the wall.", slidTiles * MPT), CU.ui.c.dim)
    g.stats.slidMetres = (g.stats.slidMetres or 0) + slidTiles * MPT
  end
  g.sliding = false
  g.slideFailed = false
  g.airBudget = nil

  metres = math.max(0, metres - (opts.freeMetres or 0))
  if P.trapAt(g, g.x, g.y) and metres >= 1 then
    P.springTrap(g, "fall", metres)
  end
  if metres >= 1 then
    local surfaceCh = M.get(map, g.x, g.y + 1)
    if Tl.isLiquid(M.get(map, g.x, g.y)) then
      P.resolveLanding(g, metres, M.get(map, g.x, g.y),
        waterDepth(map, g.x, g.y))
    else
      P.resolveLanding(g, metres, surfaceCh)
    end
  end
  return metres
end

function P.resolveLanding(g, metres, surfaceCh, waterTiles)
  if metres < 1 then return end
  CU.ui.sfx(metres >= 14 and "landhard" or "land")
  if waterTiles and waterTiles > 0 then g.body.wet = 1 end
  local ticks = math.max(1, math.floor(metres / 25))
  g:advance(ticks, { exertion = 0.4 })
  local before = CU.body.totalBleed(g.body)
  g:sayAll(CU.fall.land(g.body, metres, surfaceCh, g.rng))
  local added = CU.body.totalBleed(g.body) - before
  if added > 0.02 then g:splashBlood(math.min(0.35, added * 0.9)) end
  g.stats.fallMetres = (g.stats.fallMetres or 0) + metres
  if CU.body.totalBleed(g.body) > 0.05 then
    M.addBlood(g.map, g.x, g.y, 3)
  end
  if metres > (g.stats.longestFall or 0) then g.stats.longestFall = metres end
  if g.body.dead then g:endRun(g.body.cause) end
end

--------------------------------------------------------------------- the edge readout

function P.edgePreview(g, dx)
  local map = g.map
  local nx = g.x + dx
  if not P.fits(map, nx, g.y) then
    if P.fits(map, nx, g.y - 1) and P.fits(map, g.x, g.y - 1) then
      return { kind = "step" }
    end
    return { kind = "wall" }
  end
  if P.supported(map, nx, g.y) then return { kind = "walk" } end
  local tiles, surfaceCh = P.scanDrop(map, nx, g.y)
  local metres = tiles * MPT
  local surface = Tl.impact(surfaceCh)
  local verdict, eff = CU.fall.forecast(metres, surface, g.body.gear)
  local slideable = P.wallAt(map, nx, g.y, dx) or P.wallAt(map, nx, g.y, -dx)
  return { kind = "drop", metres = metres, surface = surface.name,
           verdict = verdict, effective = eff, slideable = slideable }
end

--------------------------------------------------------------------- walking

function P.walk(g, dx)
  local map = g.map
  local nx = g.x + dx
  g.facing = dx
  if g.body.trapped then return P.struggle(g) end
  if nx < 1 or nx > map.w then return false end

  if not P.fits(map, nx, g.y) then
    -- step up one tile if there is room above
    if P.fits(map, nx, g.y - 1) then
      local mob = CU.body.mobility(g.body)
      if mob < 0.25 then
        g:say("Your legs cannot lift you up that step.", CU.ui.c.warn)
        return false
      end
      g.x, g.y = nx, g.y - 1
      g:advance(4, { exertion = 0.6 })
      P.settle(g)
      return true
    end
    return false
  end

  local mob = CU.body.mobility(g.body)
  local cost = 2 / U.clamp(mob, 0.12, 1.3)
  if Tl.isLiquid(M.get(map, nx, g.y)) then cost = cost * 2.2 end

  -- a single-tile hole gets strided over. anything wider is a ledge, and
  -- walking off it is a decision.
  if not P.supported(map, nx, g.y) then
    local beyond = nx + dx
    if P.canStand(map, beyond, g.y) and mob > 0.35 then
      g.x = beyond
      g:advance(math.floor(cost * 1.6), { exertion = 0.6 })
      return true
    end
  end

  if mob < 0.2 then
    cost = cost * 2.2
    if not g.crawlWarned then
      g.crawlWarned = true
      g:say("Your legs will not hold you. You are crawling, and it is slow.", CU.ui.c.crit)
    end
  end

  g.x = nx
  g:advance(math.floor(cost), { exertion = 0.45 })
  if g.over then return true end
  P.settle(g)
  if not g.over then P.springTrap(g, "step") end
  return true
end

--------------------------------------------------------------------- jumping

--[[
  A jump is an arc, drawn one cell at a time so you can see it happen: you rise,
  you travel, and then gravity takes over and P.settle brings you down. Landing
  back at the height you left from costs nothing, because the rise is subtracted
  from the fall. Landing lower than you left from costs the difference.

  Push the other way in mid air and you cut the jump short. Push into a wall on
  the way down and you grab it, the same as any other fall.
]]

local function airFrame(g, hang)
  local frame = g.onFrame
  if frame then frame(g) end
  return CU.ui.pollDirection(hang or P.AIR_FRAME)
end

function P.jump(g)
  local map = g.map
  local body = g.body

  if body.trapped then return P.struggle(g) end
  if not P.supported(map, g.x, g.y) then
    g:say("You cannot jump in mid air.", CU.ui.c.dim)
    return false
  end
  local mob = CU.body.mobility(body)
  if mob < 0.45 then
    g:say("Your legs will not take a jump.", CU.ui.c.warn)
    return false
  end
  if body.energy < 6 then
    g:say("You have nothing left for a jump.", CU.ui.c.warn)
    return false
  end

  local rise = (mob >= 0.70 and 2) or 1
  local maxDrift = (mob >= 0.85 and 3) or (mob >= 0.62 and 2) or 1

  body.energy = math.max(0, body.energy - 5)
  g:advance(2, { exertion = 1.0 })
  if g.over then return true end
  CU.ui.sfx("jump")

  local startY = g.y
  local drifted = 0

  local function tryDrift(d)
    if d == 0 or drifted >= maxDrift then return false end
    if not P.fits(map, g.x + d, g.y) then return false end
    g.x = g.x + d
    g.facing = d
    drifted = drifted + 1
    return true
  end

  -- going up. whichever way you are pushing is the way you travel.
  for _ = 1, rise do
    if not P.fits(map, g.x, g.y - 1) then break end
    g.y = g.y - 1
    local d = airFrame(g)
    if tryDrift(d) then airFrame(g) end
  end

  -- a beat at the top, still steerable
  local hang = true
  while drifted < maxDrift do
    local d = airFrame(g, hang and P.APEX_HANG or nil)
    hang = false
    if not tryDrift(d) then break end
  end
  if drifted == 0 then airFrame(g, P.APEX_HANG) end

  local risen = math.max(0, startY - g.y)
  P.settle(g, { freeMetres = risen * MPT })
  if not g.over and P.trapAt(g, g.x, g.y) then P.springTrap(g, "jump") end
  return true
end

--------------------------------------------------------------------- traps

--[[
  Three of them, all sitting at standing height so you walk into them.

  Impaler   a spike. It only gives itself away with a light, two tiles out,
            and the light blinks. Walking onto it is a cut. Landing on it from
            a height is a puncture, and can take an eye or a jaw.
  Launch    a plate that throws you up and sideways, never straight up. The
            ceiling is a risk. The landing is the real one.
  Leg trap  closes on a leg and does not let go. Waiting it out bleeds you
            steadily. Struggling is faster and worse. Prying it open with your
            hands is best, if your hands still work.
]]

function P.trapAt(g, x, y)
  local ch = M.get(g.map, x, y)
  if Tl.isTrap(ch) then return ch end
  return nil
end

local function impale(g, mode, metres)
  local body = g.body
  local rng = g.rng
  local leg = rng:pick({ "lleg", "rleg" })
  local hit
  if mode == "fall" then
    local m = metres or 10
    hit = { skin = 18 + m * 0.35, muscle = 10 + m * 0.2,
            bleed = 0.10 + m * 0.006, pain = 30 + m * 0.5, shrap = 1 }
  elseif mode == "jump" then
    hit = { skin = 24, muscle = 12, bleed = 0.13, pain = 30 }
  else
    hit = { skin = 12, muscle = 5, bleed = 0.055, pain = 16 }
  end
  g:say("A spike goes through your " .. D.LIMBS[leg].name .. ".", CU.ui.c.crit)
  CU.ui.sfx("bitten")
  g:sayAll(CU.body.hurt(body, hit, rng, { limb = leg, silent = true }))
  M.addBlood(g.map, g.x, g.y, 3)

  -- coming down on one face first is a different injury altogether
  if mode == "fall" then
    local m = metres or 10
    if rng:chance(U.clamp((m - 8) / 60, 0, 0.5)) then
      CU.body.hurt(body, { skin = 30, muscle = 14, bleed = 0.16, pain = 60 },
        rng, { limb = "head", silent = true })
      if rng:chance(0.5) and not body.eyeLost then
        body.eyeLost = true
        g:say("It takes an eye. You will not see as well down here again.", CU.ui.c.crit)
      else
        body.limbs.head.bone = "dislocated"
        body.limbs.head.boneTimer = D.TUNE.DISLO_HEAL_MIN
        g:say("Your jaw comes away from the joint. Nothing solid is going in it.",
          CU.ui.c.crit)
      end
      CU.ui.sfx("crack")
    end
  end
end

local function launch(g)
  local map = g.map
  local body = g.body
  local rng = g.rng
  g:say("The plate throws you.", CU.ui.c.warn)
  CU.ui.sfx("jump")

  local dx = rng:chance(0.5) and 1 or -1
  if not P.fits(map, g.x + dx, g.y) then dx = -dx end
  local rise = rng:int(3, 5)
  local across = rng:int(2, 4)
  g.facing = dx

  local risen = 0
  for i = 1, rise do
    if not P.fits(map, g.x, g.y - 1) then
      -- the ceiling stops you before the arc does
      CU.body.hurt(body, { skin = 7, muscle = 6, pain = 22 }, rng,
        { limb = "head", silent = true })
      if rng:chance(0.3) then
        body.brain = U.clamp(body.brain - rng:range(1, 4), 0, 100)
      end
      g:say("You hit the ceiling.", CU.ui.c.crit)
      CU.ui.sfx("crack")
      break
    end
    g.y = g.y - 1
    risen = risen + 1
    if i <= across and P.fits(map, g.x + dx, g.y) then g.x = g.x + dx end
    local frame = g.onFrame
    if frame then frame(g) end
    if not CU.ui.headless then CU.ui.pollDirection(P.AIR_FRAME) end
  end
  P.settle(g, { freeMetres = risen * MPT })
end

local function snap(g)
  local body = g.body
  local rng = g.rng
  local leg = rng:pick({ "lleg", "rleg" })
  if body.limbs[leg].amputated then leg = (leg == "lleg") and "rleg" or "lleg" end
  body.trapped = { limb = leg, timer = P.TRAP_SECONDS, struggles = 0 }
  g:say("A leg trap closes on your " .. D.LIMBS[leg].name .. ".", CU.ui.c.crit)
  CU.ui.sfx("crack")
  g:sayAll(CU.body.hurt(body, {
    skin = 20, muscle = 13, bleed = 0.10, pain = 44, frac = 0.12,
  }, rng, { limb = leg, silent = true }))
  M.addBlood(g.map, g.x, g.y, 2)
end

P.TRAP_SECONDS = 8

-- mode is "step", "jump" or "fall"
function P.springTrap(g, mode, metres)
  local ch = P.trapAt(g, g.x, g.y)
  if not ch then return false end
  local d = Tl.get(ch)
  if d.id == "impaler" then
    impale(g, mode, metres)
    return true
  elseif d.id == "jumppad" then
    if mode ~= "launch" then launch(g) end
    return true
  elseif d.id == "beartrap" then
    M.set(g.map, g.x, g.y, " ")        -- it only closes once
    snap(g)
    return true
  end
  return false
end

-- Fighting the trap. Faster than waiting, and it costs you.
function P.struggle(g)
  local body = g.body
  local t = body.trapped
  if not t then return false end
  t.struggles = t.struggles + 1
  local leg = t.limb
  g:sayAll(CU.body.hurt(body, {
    skin = 6, muscle = 4, bleed = 0.06, pain = 14,
  }, g.rng, { limb = leg, silent = true }))
  M.addBlood(g.map, g.x, g.y, 1)
  t.timer = t.timer - 3
  g:advance(3, { exertion = 1.0 })
  CU.ui.sfx("hurt")
  if t.timer <= 0 then
    body.trapped = nil
    g:say("The jaws come apart and you drag the leg out.", CU.ui.c.ok)
  else
    g:say("It does not let go. " .. math.ceil(t.timer) .. " seconds of it left.",
      CU.ui.c.warn)
  end
  return true
end

-- Working it open with your hands. Slower, but it does not tear the leg up.
function P.pryTrap(g)
  local body = g.body
  local t = body.trapped
  if not t then return false end
  local grip = CU.body.grip(body)
  if grip < 0.25 then
    g:say("Your hands cannot open it. You will have to pull.", CU.ui.c.warn)
    return false
  end
  g:advance(6, { exertion = 0.9 })
  if g.rng:chance(U.clamp(0.3 + grip * 0.6, 0.2, 0.92)) then
    body.trapped = nil
    g:say("You get both hands into the jaws and force them apart.", CU.ui.c.ok)
    CU.ui.sfx("confirm")
  else
    t.timer = math.max(0, t.timer - 2)
    g:say("It slips. Try again.", CU.ui.c.warn)
  end
  return true
end

--------------------------------------------------------------------- water

function P.waterHere(g)
  local map = g.map
  -- a spring beats a pool, so standing in dirty water beside one still gets you
  -- the clean drink
  for dx = -2, 2 do
    for dy = 0, 1 do
      if Tl.get(M.get(map, g.x + dx, g.y + dy)).id == "spring" then
        return true, true
      end
    end
  end
  if Tl.isLiquid(M.get(map, g.x, g.y)) then return true, false end
  if Tl.isLiquid(M.get(map, g.x, g.y + 1)) then return true, false end
  return false, false
end

-- Kneel and drink straight from it. No flask needed.
function P.drink(g)
  local ok, clean = P.waterHere(g)
  if not ok then return false end
  local body = g.body
  if body.thirst >= 118 then
    g:say("You have had enough.", CU.ui.c.dim)
    return true
  end
  g:advance(18, { exertion = 0.05 })
  if g.over then return true end
  body.thirst = U.clamp(body.thirst + 34, 0, 120)
  if clean then
    g:say("You kneel and drink. Clean.", CU.ui.c.ok)
  else
    body.sick = U.clamp(body.sick + 11, 0, 100)
    g:say("You kneel and drink. It tastes of the rock, and it may cost you later.",
      CU.ui.c.warn)
  end
  CU.ui.sfx("heal")
  return true
end

--------------------------------------------------------------------- mining

--[[
  Breaking through rock by hand, one tile at a time.

  Each swing puts work into the tile in front of you. Stone takes about a hundred
  points; a rock hammer does forty six a swing, a pry bar twenty six, bare hands
  six. Every swing costs energy, and energy only comes back by resting, so a long
  tunnel means stopping halfway. Swinging with nothing in your hands tears them up.

  Target order: the tile ahead at foot level, then the tile ahead at chest level,
  then the ceiling, then the floor. Break the two ahead of you and you can walk
  through. Break the ceiling and you can jump up out of a hole.
]]

P.MINE_ENERGY_TOOL = 3.2
P.MINE_ENERGY_BARE = 4.5
P.MINE_BARE_POWER  = 9
P.MINE_MIN_ENERGY  = 4

function P.mineTarget(g, hint)
  local map = g.map
  local dx = g.facing or 1
  local order
  if hint == "up" then
    order = { { g.x, g.y - 2, "above" } }
  elseif hint == "down" then
    order = { { g.x, g.y + 1, "below" } }
  else
    order = {
      { g.x + dx, g.y,     "ahead" },
      { g.x + dx, g.y - 1, "ahead" },
      { g.x,      g.y - 2, "above" },
      { g.x,      g.y + 1, "below" },
    }
  end
  for _, t in ipairs(order) do
    local ch = M.get(map, t[1], t[2])
    if Tl.digCost(ch) and not Tl.passable(ch) then
      return t[1], t[2], ch, t[3]
    end
  end
  if hint then return nil end
  -- a plank deck underfoot can be broken out too
  local ch = M.get(map, g.x, g.y + 1)
  if Tl.digCost(ch) then return g.x, g.y + 1, ch, "below" end
  return nil
end

function P.mine(g, hint)
  local map = g.map
  local body = g.body
  local x, y, ch, where = P.mineTarget(g, hint)
  if not x then
    g:say(hint and ("Nothing to break " .. hint .. " there.")
      or "There is nothing here you can break through.", CU.ui.c.dim)
    return false
  end

  if body.energy < P.MINE_MIN_ENERGY then
    g:say("You are too tired to swing again. Rest first.", CU.ui.c.warn)
    return false
  end
  if CU.body.grip(body) < 0.2 then
    g:say("You cannot grip hard enough to swing.", CU.ui.c.warn)
    return false
  end

  local weapon = g.inv.weapon
  local wdef = weapon and D.ITEMS[weapon.id]
  local digPower = wdef and wdef.weapon and wdef.weapon.dig or 0
  local bare = digPower <= 0
  local power = (bare and P.MINE_BARE_POWER or digPower)
    * U.clamp(CU.body.swingPower(body), 0.15, 1.6)
  if body.energy < 25 then power = power * 0.6 end

  local cost = bare and P.MINE_ENERGY_BARE or P.MINE_ENERGY_TOOL
  body.energy = math.max(0, body.energy - cost)

  local swingTime = math.floor(16 / U.clamp(CU.body.swingPower(body), 0.2, 1.6))
  g:advance(swingTime, { exertion = 0.95 })
  if g.over then return true end
  CU.ui.sfx("mine")

  if bare then
    local arm = (g.rng:chance(0.5)) and "larm" or "rarm"
    CU.body.hurt(body, { skin = 1.6, pain = 2.4 }, g.rng, { limb = arm, silent = true })
  end

  -- the noise carries
  for _, e in ipairs(map.entities) do
    if not e.dead and not e.awake then
      if math.abs(e.x - g.x) + math.abs(e.y - g.y) * 2 < 16 then e.awake = true end
    end
  end

  local total = Tl.digCost(ch)
  local done = M.digAt(map, x, y) + power
  if done < total then
    M.setDig(map, x, y, done)
    g:say(string.format("You work at the rock %s. %d%%.", where,
      math.floor(done / total * 100)), CU.ui.c.dim)
    return true
  end

  M.clearDig(map, x, y)
  M.set(map, x, y, " ")
  g.stats.mined = (g.stats.mined or 0) + 1
  CU.ui.sfx("breakout")
  g:say("The rock " .. where .. " breaks through.", CU.ui.c.ok)

  local drop = Tl.digDrop(ch)
  if drop and D.ITEMS[drop] and g.rng:chance(0.6) then
    CU.inv.add(g.inv, drop, 1)
    CU.inv.updateGear(g.inv, body)
  end
  if where == "below" then P.settle(g) end
  return true
end

--------------------------------------------------------------------- climbing

function P.climb(g, dy)
  local map = g.map
  local here = M.get(map, g.x, g.y)
  local target = M.get(map, g.x, g.y + dy)
  local td = Tl.get(target)

  if dy > 0 and (td.shaft or td.hatch) then return "exit" end

  local onClimb = Tl.isClimb(here)
  local intoClimb = Tl.isClimb(target)

  if g.body.trapped then return P.struggle(g) end

  if dy < 0 then
    if not (onClimb or intoClimb) then
      -- nothing to climb, so up means dig up. that is how you get out of a hole.
      if P.mineTarget(g, "up") then return P.mine(g, "up") end
      g:say("There is nothing here to climb or break through.", CU.ui.c.dim)
      return false
    end
    if not P.fits(map, g.x, g.y - 1) then return false end
    if CU.body.grip(g.body) < 0.25 then
      g:say("Your arms cannot grip well enough to climb.", CU.ui.c.warn)
      return false
    end
    g.y = g.y - 1
    g:advance(4, { exertion = 0.8 })
    return true
  end

  if onClimb or intoClimb then
    if not Tl.passable(target) then
      g:say("That is the bottom of the climb.", CU.ui.c.dim)
      return false
    end
    g.y = g.y + 1
    g:advance(3, { exertion = 0.5 })
    if g.over then return true end
    P.settle(g)
    return true
  end

  if P.waterHere(g) then return P.drink(g) end

  local below = M.get(map, g.x, g.y + 1)
  local bd = Tl.get(below)
  if bd.platform and not bd.solid then
    g.y = g.y + 1
    P.settle(g)
    return true
  end

  if P.mineTarget(g, "down") then return P.mine(g, "down") end
  g:say("Nothing to climb here. Walk off a ledge, jump, or find a rope.", CU.ui.c.dim)
  return false
end

--------------------------------------------------------------------- creatures

function P.stepEntities(g)
  local map = g.map
  for _, e in ipairs(map.entities) do
    if not e.dead then
      local def = D.CREATURES[e.id]
      if def then
        local dx = g.x - e.x
        local dy = g.y - e.y
        local dist = math.abs(dx) + math.abs(dy) * 2
        local range = 5 + def.senses * 7 + CU.inv.lightRadius(g.inv)

        if dist <= 1 and math.abs(dy) <= 1 then
          if (e.cooldown or 0) <= 0 then
            g.stats.encounters = g.stats.encounters + 1
            CU.combat.begin(g, e)
            e.cooldown = 4
            e.patience = 0
          end
        elseif dist < range and math.abs(dy) <= 3 then
          if not e.seenBy then
            e.seenBy = true
            g:say(def.name .. " has noticed you.", CU.ui.c.warn)
          end
          e.awake = true
          e.patience = (e.patience or 0) + 1
        elseif e.awake then
          e.patience = (e.patience or 0) + 1
          if e.patience > 30 then
            e.awake = false; e.patience = 0; e.seenBy = false
          end
        end

        if e.awake and dist > 1 then
          e.step = (e.step or 0) + (def.speed or 1) * 0.6
          while e.step >= 1 do
            e.step = e.step - 1
            local sx = dx > 0 and 1 or (dx < 0 and -1 or 0)
            local nx = e.x + sx
            -- they will not follow you off a ledge or down a rope
            if sx ~= 0 and Tl.passable(M.get(map, nx, e.y)) and P.supported(map, nx, e.y) then
              e.x = nx
            elseif sx ~= 0 and Tl.passable(M.get(map, nx, e.y - 1))
                   and Tl.passable(M.get(map, e.x, e.y - 1))
                   and P.supported(map, nx, e.y - 1) then
              e.x, e.y = nx, e.y - 1
            end
          end
        end
        if (e.cooldown or 0) > 0 then e.cooldown = e.cooldown - 1 end
      end
    end
  end
end

--------------------------------------------------------------------- vision

function P.reveal(g)
  local map = g.map
  local r = math.max(3, math.floor(CU.inv.lightRadius(g.inv) * 2.6))
  local rv = math.max(3, math.floor(r * 0.72))
  for dy = -rv, rv do
    for dx = -r, r do
      if dx * dx + (dy * 2.1) * (dy * 2.1) <= r * r then
        M.markSeen(map, g.x + dx, g.y + dy - 1)
      end
    end
  end
  g.lightR = r
  g.lightRv = rv
end

CU.phys = P
return P

end
]=])

put("lib/render.lua", [=[
-- WRITE-OFF / lib/render.lua
-- Draws the map. Rock is a filled block, not a hash, so the cave reads at a glance.

return function(CU)

local U = CU.util
local D = CU.data
local Tl = CU.tiles
local M = CU.mapgen
local UI = CU.ui
local R = {}

--------------------------------------------------------------------- blit codes

local HEX = {
  [colors.white] = "0", [colors.orange] = "1", [colors.magenta] = "2",
  [colors.lightBlue] = "3", [colors.yellow] = "4", [colors.lime] = "5",
  [colors.pink] = "6", [colors.gray] = "7", [colors.lightGray] = "8",
  [colors.cyan] = "9", [colors.purple] = "a", [colors.blue] = "b",
  [colors.brown] = "c", [colors.green] = "d", [colors.red] = "e",
  [colors.black] = "f",
}
local function hex(c) return HEX[c] or "0" end
R.hex = hex

--------------------------------------------------------------------- tile looks

-- glyph, foreground, background
local function look(glyph, fg, bg) return { glyph, fg, bg } end

local BLOOD_GLYPH = { [1] = ".", [2] = ",", [3] = ":" }

local LIT = {
  [" "] = look(" ", colors.black,     colors.black),
  ["#"] = look(" ", colors.gray,      colors.gray),
  ["%"] = look(".", colors.lightGray, colors.brown),
  ["o"] = look(".", colors.lightGray, colors.gray),
  ["^"] = look("^", colors.orange,    colors.gray),
  ['"'] = look(",", colors.lime,      colors.green),
